(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["zh"] = {"ui":{"lead":"人们不只玩游戏，还把游戏画了下来。放大这些跨越3300年的绘画和雕像，看看其中的细节吧。","details":"看点","links":"查看或游玩这款游戏","record":"作品信息","game":"游戏","exhibit":"馆藏","room":"展厅","room_chance":"掷具","hint":"双指或滚轮缩放 · 拖动移动 · 点击编号","r_artist":"作者","r_date":"年代","r_place":"地区","r_medium":"材质与技法","r_size":"尺寸","r_museum":"收藏","r_credit":"入藏","r_rights":"图像","met":"大都会艺术博物馆","cc0":"开放获取（公有领域）","metlink":"博物馆的作品页面","credit":"图像来自大都会艺术博物馆、克利夫兰艺术博物馆、芝加哥艺术博物馆和阿姆斯特丹国家博物馆的开放获取（公有领域）。","cma":"克利夫兰艺术博物馆","aic":"芝加哥艺术博物馆","rijks":"阿姆斯特丹国家博物馆"},"nefertari":{"title":"下塞尼特棋的奈菲尔塔利王后","artist":"尼娜·德·加里斯·戴维斯（摹本）","date":"原画 约公元前1290—前1224年 · 摹本 1921—22年","place":"埃及（王后谷）","game":"塞尼特","medium":"纸本蛋彩（原尺寸二分之一的摹本）","p":["奈菲尔塔利是拉美西斯二世的正妃。这幅画是1921—22年在王后谷她的墓中临摹的壁画，连原画的裂缝和缺损都照样画了下来。","王后坐在棋盘前，与一位看不见的对手下塞尼特。人们认为，画在墓中的塞尼特不只是游戏，还意味着赢得通往来世的旅程。"],"spots":[["两种棋子","棋盘上排着尖顶的棋子和线轴形的棋子，分属对局的两方。"],["王后的手","正要拈起棋子的指尖。"],["棋盘与台架","棋盘从侧面画出，所以看不到格子。它放在细脚的台架上。"],["名字的框","椭圆形的框（王名圈）里写着王后的名字。"],["看不见的对手","对面没有人，王后在和看不见的对手对局。"]]},"hydria":{"title":"下棋的阿喀琉斯与埃阿斯（水罐）","artist":"归于莱阿格罗斯画组","date":"约公元前510年","place":"希腊（阿提卡）","game":"骰子游戏","medium":"陶（黑绘式）","p":["特洛伊战争的营地里，希腊两位英雄阿喀琉斯和埃阿斯围着棋盘消磨时光。这一图样是约公元前540年由陶工兼画家埃克塞基亚斯创造的，原作保存在梵蒂冈博物馆的双耳瓶上。","约公元前540至前480年间，这个题材非常受欢迎，已知有150多例。这只水罐的正中站着女神雅典娜。两人玩的是掷骰子走棋子的游戏。"],"spots":[["女神雅典娜","女神雅典娜站在两人中间。"],["左边的英雄","手里仍握着长矛，俯身看着棋盘。"],["右边的英雄","他也没有放下武器——战争中片刻的游戏。"],["棋盘","两人之间的矮台就是棋盘。"],["肩部的画","罐肩上画着出发的战车。"]]},"liubo":{"title":"下六博的两人（随葬俑）","date":"公元前1世纪—公元1世纪","place":"中国（汉）","game":"六博","medium":"彩绘陶","p":["这是两位下六博的人像。六博在汉代风行一时。这样的俑放进墓中，寄托着死后也能继续享乐的愿望。","照片中，两人之间摆着本馆馆藏的六博棋盘和骨制棋子。人像捕捉了一局激战中的戏剧性瞬间。"],"spots":[["六博棋盘","与本馆馆藏“六博棋盘与棋子”是同一块棋盘，可以看到T、L、V形记号。"],["左边的棋手","沉着地盯着棋盘。"],["右边的棋手","一只手举起，嘴巴张得大大的，是走出了好棋吗？"],["盘上的棋子","骨制棋子排在棋盘两端。"],["盘外的棋子","地上也放着棋子。"]]},"shahnama":{"title":"布祖尔吉米赫尔破解印度的游戏“象棋”（《塔赫马斯普国王的列王纪》）","artist":"归于阿卜杜勒·瓦哈卜","date":"约1530—35年","place":"伊朗（大不里士）","game":"国际象棋","medium":"纸本不透明水彩、墨、银、金","p":["这是菲尔多西史诗《列王纪》中的一幕。印度国王派使者带来象棋的棋盘和棋子，向波斯国王努希尔万挑战：“如果能解出玩法，印度就纳贡。”","只有年轻的贤者布祖尔吉米赫尔在期限内解开了谜题。《列王纪》还说，波斯回赠了双陆，而印度没能解开。国王和廷臣们都目不转睛地盯着棋盘和棋手。"],"spots":[["棋盘","方格棋盘上摆着棋子，小到几乎看不清形状。"],["努希尔万国王","坐在宝座上，等着看谜题如何解开。"],["围着棋盘的人","俯身看着棋盘的棋手们。"],["诗句","上下的框里写着菲尔多西的诗。"],["廷臣们","头戴竖着红棒的头巾的人们，站着观看。"]]},"chaupar":{"title":"下乔帕尔的湿婆与帕尔瓦蒂（《拉萨曼贾里》组画之一）","artist":"努尔布尔的德维达萨","date":"1694—95年","place":"印度（巴索利，查谟）","game":"乔帕尔（鲁多祖先的近亲）","medium":"纸本不透明水彩、墨、银、金","p":["这是描绘15世纪梵文爱情诗《拉萨曼贾里》的组画中的一幅。湿婆神和妻子帕尔瓦蒂坐在虎皮上，围着十字形的棋盘。","湿婆作弊赢走了帕尔瓦蒂的项链，她正请求还给她。大胆的色彩、模糊的空间深度，用色彩和手势表达含义，是巴索利画派的特点。"],"spots":[["十字形棋盘","乔帕尔和帕奇西的棋盘就是这样的十字形。"],["盘上的白条","应是乔帕尔所用的长骰子（帕萨）。"],["湿婆","白色的身体，颈上缠着蛇。"],["帕尔瓦蒂","伸出手，请求还她项链。"],["虎皮","两人坐在虎皮上。"]]},"shogi":{"title":"下将棋的青年男女（《中纳言兼辅》，三十六歌仙比拟）","artist":"铃木春信","date":"约1767—69年","place":"日本（江户）","game":"将棋","medium":"木版画（锦绘）","p":["这是比拟三十六歌仙的组画之一，这一幅比拟的是中纳言兼辅。夏夜，蚊帐旁，一对青年男女围着将棋盘。","春信是推广多色套印“锦绘”的画师。连棋盘上棋子的排列都画得很细致。"],"spots":[["带脚的将棋盘","和今天一样带脚的厚棋盘。"],["小盒子","应是收纳棋子的盒子。"],["蚊帐","挂着绿色的蚊帐，是夏夜的场景。"],["行灯","照亮棋盘的灯。"],["和歌牌","云形的框里写着歌仙的名字和和歌。"]]},"sugoroku":{"title":"玩双六的两位少女","artist":"初代歌川丰国","date":"江户时代（18世纪末—19世纪初）","place":"日本（江户）","game":"盘双六（双陆的一种，与西洋双陆同类）","medium":"木版画（双联）","p":["两张版画拼成的大画面上，聚在客厅里的少女们正在玩盘双六。盘双六与本馆馆藏的正仓院双六局一脉相承，是西洋双陆的同类。","棋盘上排着黑白棋子，右边的少女手里拿着筒（摇骰子的容器）。窗外可以看到富士山。"],"spots":[["双六盘","细长的格子上排着黑白棋子。"],["骰筒","把骰子放进筒里摇。"],["盘外的棋子","是已经走完的棋子，还是还没上盘的棋子？"],["富士山","窗外的富士山。"],["两张的接缝","两张版画在这里相接。"]]},"eakins":{"title":"下国际象棋的人","artist":"托马斯·埃金斯","date":"1876年","place":"美国（费城）","game":"国际象棋","medium":"木板油画","p":["在费城一户人家的客厅里，两位朋友在下国际象棋，画家的父亲本杰明·埃金斯在一旁观看。精心构建空间、细致描绘细节，是画家在巴黎师从热罗姆时学到的。","1881年，这幅画成为大都会艺术博物馆接受的第一件在世画家的捐赠作品。"],"spots":[["棋子","昏暗的房间里，棋盘上的棋子格外明亮。"],["画家的父亲","站着观战的是画家的父亲本杰明。"],["右边的棋手","画家乔治·W·霍姆斯，画家父亲的朋友。"],["桌子的抽屉","写着拉丁文，意思是“本杰明·埃金斯之子绘于76年”。"],["壁炉上方的画","挂着老师热罗姆画作的复制品。"],["猫","地板上，只有猫对棋局毫无兴趣。"]]},"weiqi":{"title":"仙人对弈图盘","artist":"佚名","date":"1425—1436年（明宣德年间）","place":"中国","game":"围棋","medium":"剔红剔绿（雕漆）","size":"高3.5、宽14.9、长23.5厘米","credit":"弗洛伦斯与赫伯特·欧文夫妇捐赠，2015年","p":["这是一件雕漆盘：先髹涂数十层漆再雕刻，红漆之下有一层绿漆，靠雕刻深浅显出不同颜色。花口盘心里，刻着在松树下对弈的仙人。","中国有“烂柯”的传说：樵夫王质在山中观看仙人下棋，回过神来，斧柄已经烂掉，人间已过了很久。对弈的仙人是很受欢迎的题材。右边站着的人物是谁，没有记载。"],"spots":[["棋盘","两位仙人之间的棋盘，连棋盘线都细细刻出。"],["对弈的仙人","坐在岩石旁围着棋盘的两人。"],["站着观看的人","稍远处站着的人物，令人想起烂柯传说中的樵夫，但具体是谁不得而知。"],["月","天上一轮圆月（也可能是太阳）。"],["松","枝干舒展的松树，常象征长寿与仙境。"],["牡丹边饰","盘缘雕有大朵牡丹与枝叶。"]]},"webb":{"title":"双陆棋手（陈列柜）","artist":"菲利普·韦布（设计）、爱德华·伯恩-琼斯（绘画）、莫里斯-马歇尔-福克纳公司（制作）","date":"1861年","place":"英国（伦敦）","game":"双陆棋（西洋双陆）","medium":"彩绘松木、皮革上油彩、黄铜、铜","size":"高185.4、宽114.3、深53.3厘米","credit":"罗杰斯基金，1926年","p":["这是威廉·莫里斯与友人于1861年创办的公司最早期的家具之一。柜门的皮革上用油彩画着身穿中世纪服装的一男一女正在下双陆。它还在1862年的伦敦国际博览会上展出。","它很好地体现了工艺美术运动想要消除“美术”与“工艺”界限的理念。皮革背景上打出细密的小点，是仿照中世纪的技法。"],"spots":[["棋盘","两人之间桌上的双陆棋盘。"],["男子","手拿棋子、凝视棋盘的年轻男子。"],["女子","坐在对面的女子，手里拿着棋子（或骰盅）。"],["脚边的花","两人的脚边开着花。"],["打点的皮革","背景皮革上打出细密的小点，在光下闪烁。"],["菱形纹带","柜门上下围着金底菱形纹样的饰带。"]]},"liberale":{"title":"下棋的人们","artist":"利贝拉莱·达·维罗纳","date":"约1475年","place":"意大利（维罗纳）","game":"国际象棋","medium":"木板蛋彩","size":"34.9×41.3厘米","credit":"梅特兰·F·格里格斯遗赠，1943年","p":["这是文艺复兴时期意大利“卡索内”（装新娘嫁妆的彩绘箱）正面板画的残片。画家利贝拉莱也以为锡耶纳大教堂的唱诗本绘制插图而闻名。","画的是一个不知名爱情故事里的场景。另一块残片上，窗边的少女似乎在招呼青年进来；这幅画里，两人正在下国际象棋。据美术馆的解说，少女快要输了。国际象棋是当时爱情文学里常用来比喻情场较量的题材。"],"spots":[["棋盘","红白相间的棋盘上摆着深色棋子，棋局似乎已近尾声。"],["青年","伸手向棋盘的青年，看来这局他要赢了。"],["少女","坐在对面的少女；在另一块残片上，她从窗口招呼青年。"],["窗外","敞开的窗外是山丘和天空。"],["观棋的青年们","抱着双臂看棋的男子们。"],["观棋的少女们","从柱子后面探看棋局的少女们。"]]},"mirror":{"title":"下国际象棋的恋人镜盒","artist":"佚名","date":"1325—1350年","place":"法国（巴黎）","game":"国际象棋","medium":"象牙","size":"直径10.2厘米","credit":"J·H·韦德基金购藏，1940年","p":["这块手掌大小的象牙圆片，原本是手镜的盖子。14世纪的巴黎人把磨亮的金属镜夹在两片象牙板之间随身携带；这样的象牙雕刻是宫廷和贵族喜爱的奢侈品。","挂着帷幕的帐篷里，一位青年和一位女士正在下国际象棋。在中世纪的故事里，国际象棋同时象征爱情与战争。有人认为两人是特里斯坦与伊索尔德，或兰斯洛特与桂妮薇儿，但并无定论。美术馆向观众发问：你觉得谁会赢？"],"spots":[["棋盘","放在独脚桌上的棋盘，上面立着几枚棋子。"],["青年","他伸手去走下一步棋。"],["女士","戴头巾的女士，指尖碰着盘上的棋子。"],["握着的手","另一只手握着放在膝上。是握着吃掉的棋子吗？"],["帐篷的帷幕","两侧系起的帷幕——这是刻有下棋场景的镜盒常见的舞台。"]]},"morris":{"title":"莫里斯棋（九子棋）棋盘","artist":"彼得·弗勒特纳","date":"1500—1546年","place":"德国","game":"九子莫里斯棋","medium":"木刻版画","credit":"查尔斯·W·哈克尼斯基金，1923年","p":["这是活跃于文艺复兴时期纽伦堡的雕塑家彼得·弗勒特纳的木刻版画。他还以装饰图样、家具、金匠的模型和一副讽刺意味十足的扑克牌设计而闻名。卷曲的蔓草纹下藏着的，是德语称为“磨坊”（Mühle）的九子莫里斯棋盘：三个套在一起的正方形，在各边中点相连。","棋盘上有24个点。把自己的三枚棋子连成一线（成“磨”），就能吃掉对方一枚。这样的版画也是工匠的范本，美术馆曾把这张作品放进金匠模型与图样的展览。人们是直接在纸上下棋，还是把它刻到木头或金属上，没有留下记录。"],"spots":[["中心的正方形","最里面的正方形，填满细密的蔓草纹。"],["外圈的角","外侧正方形的角——放棋子的24个点之一。"],["中圈的角","中间正方形的角也是放棋子的点。"],["相连的线","在各边中点连接三个正方形的带子，棋子也沿着它走。"],["面具","上下左右是卷曲的饰框和人脸，典型的文艺复兴怪诞纹样。"],["葡萄藤边框","叶子和果实在黑底上刻成白色。"]]},"leifeng":{"title":"雷峰塔棋盘","artist":"佚名","date":"1736—1795年（乾隆年间）","place":"中国","game":"竞走棋（掷骰前进）","medium":"木版画，纸本墨印","size":"31×29.8厘米","credit":"J·H·韦德基金购藏，2025年","p":["这是清代乾隆年间印制、用来玩的单张印刷品。格子里画的是民间故事《白蛇传》的人物：白蛇精白娘子（白娘）、她的同伴小青、青年许宣（后来的版本作许仙），以及最后把白娘子镇压在西湖边雷峰塔下的法海和尚。","路线从写着“起马”的格子盘旋着通向中心的塔。玩家大概像西方的鹅棋那样，掷骰子沿着故事比赛前进，但玩法没有留下记录。据美术馆介绍，这类彩色单张版画在城市里出售，挂在墙上，成为城市视觉文化的一部分；每种颜色都用单独刻的版来印。"],"spots":[["起马","写着“起马”的格子，应该是起点。"],["白娘与小青","白蛇精白娘子和她的同伴小青。"],["许宣","与白娘子结为夫妻的青年。"],["法海禅师","把白娘子镇在塔下的和尚。"],["雷峰塔","杭州西湖边的雷峰塔，故事结束的地方。"],["中心","塔前坐着的女子和跪着的男子——故事最后一幕，也许就是终点。"]]},"tutinama":{"title":"受伤的猴子咬了棋友王子的手（《鹦鹉故事》插图）","artist":"达萨万塔","date":"约1560年","place":"印度（阿克巴的莫卧儿宫廷）","game":"国际象棋","medium":"纸本水粉、墨、金","size":"20×14.2厘米（画面10.2×10.6厘米）","credit":"A·迪恩·佩里夫人捐赠，1962年","p":["这是莫卧儿帝国阿克巴宫廷制作的故事集《鹦鹉故事》（Tuti-nama）的插图。母鹦鹉给孩子们讲故事，告诫它们不要和狐狸崽这样不同种类的动物交朋友，这是其中一则：一只擅长国际象棋的猴子，常常和王子下棋。","有一天王子宴客，猴子在席上开了个失礼的玩笑，被王子打了一巴掌，猴子便咬了王子的手。右边屋外仆人在准备饭菜，客人们看得目瞪口呆。下方的题记写着达萨万塔的名字，他后来成为莫卧儿宫廷最著名的画家之一；年轻的他在画面下先涂了一层清凉的蓝色。"],"spots":[["猴子","咬住王子的手——它是王子的棋友。"],["王子","被咬了手的王子。"],["棋盘","放在地上的红格棋盘。"],["吃惊的客人","应邀赴宴的客人们。"],["准备饭菜","外面把锅架在火上的仆人们。"],["波斯文","上方框里用波斯文写着故事。"]]},"teniers":{"title":"双陆对局","artist":"大卫·特尼尔斯","date":"17世纪40年代","place":"佛兰德","game":"西洋双陆","medium":"木板油画，后转移到画布","size":"59×80.6厘米","credit":"塞缪尔·D·怀斯夫妇捐赠，1943年","p":["佛兰德画家特尼尔斯画的一场押了重注的西洋双陆大战。这种游戏历史悠久，现代形式出现于15世纪，而“backgammon”这个名字大约就诞生在这幅画的年代。17世纪它非常流行，常常用来赌钱。","两位对手周围挤满看客，墙边还有人在记分。从窗口探头的女人等细节看，美术馆认为这里是妓院里的赌博间。这类游戏场景常带着训诫：赌博愚蠢、甚至邪恶，而且浪费时间。"],"spots":[["棋盘","桌上打开的双陆棋盘，对局正在进行。"],["白衬衫的男人","背对我们的棋手，正伸手去拿棋子。"],["托腮的男人","对面的棋手，托着腮陷入沉思。"],["记分的人","在墙上的板子上做记号的男人——记的是分数还是赌注？"],["窗口的女人","从窗口往下看的年长女人。"],["里屋","里屋的男人们在一位年轻女子身旁喝酒。"]]},"imari":{"title":"下围棋的两人方盘","artist":"佚名","date":"18世纪","place":"日本（江户时代）","game":"围棋","medium":"瓷器，模制，釉上彩（肥前窑，伊万里风格）","size":"2.4×13.8厘米","credit":"塞弗伦斯与格丽塔·米利金收藏，1964年","p":["这只小小的方盘上，两人在松树下下围棋：穿黄衣的人对着直接放在地上的棋盘坐着，穿绿衣的对手靠在树上。","这是肥前（今佐贺、长崎）烧制的伊万里瓷器，绿色的用法让人想起九谷彩绘。它是为外销而做的——当时日本已取代中国，成为欧洲瓷器的主要供应者。"],"spots":[["棋盘","画着格子的围棋盘，直接放在地上。"],["黄衣人","面向棋盘坐着的人。"],["绿衣人","靠在树上微笑的对手。"],["松树","在头顶伸展枝条的松树。"],["红框","切去四角的红框围住画面。"]]},"shoei":{"title":"琴棋书画图屏风（一扇）","artist":"传狩野松荣","date":"16世纪末—17世纪初","place":"日本（桃山时代）","game":"围棋","medium":"六曲一双之一，纸本墨画淡彩","size":"153×358.6厘米","credit":"约翰·L·塞弗伦斯基金，1979年","p":["这是传为狩野派画家狩野松荣所作的六曲屏风。它和另一扇成对，描绘中国文人应具备的修养“琴棋书画”——弹琴、下棋、书法和绘画。松树下的原野上，身份高贵的中国士人带着仆从在休憩。","画面中央两人在下围棋，另一人在旁观看。旁边的桌上放着书和仍装在布套里的琴，等着人来弹。这是一幅娱乐与礼仪兼顾的场景。据美术馆介绍，有个仆人被水里游动的鱼吸引了注意。"],"spots":[["棋盘","带脚的棋盘，两位士人相对而弈。"],["士人们","对弈的两人，和在旁观看的一人。"],["桌上","应是放着书和套中之琴的桌子。"],["仆从","在桌边侍候的仆从。"],["看鱼的仆人","趴在水边，看着鱼游动的仆人。"],["松树","在画面上方伸展枝条的大松树。"]]},"umaya":{"title":"马厩图屏风（廊下的围棋与将棋）","artist":"作者不详","date":"16世纪前期","place":"日本（室町时代）","game":"围棋、将棋","medium":"六曲一双屏风之一；纸本设色、金","size":"146.1×346.6厘米","credit":"爱德华·L·惠特莫尔基金购藏，1934年","p":["这是由6扇连成的屏风，左右两件为一组，这是其中之一。主题或许是马厩里拴着的名马，但前面的廊下也热闹非凡。","廊下的人们在下两种棋：左边是围棋，右边是将棋。按美术馆的解说，躁动的马匹与静心谋划的棋局相映成趣，使画面充满生气。在日本，猴子被视为马的守护者，马厩里有时也养猴。"],"spots":[["围棋盘","画着细密格线、摆着黑子的棋盘。"],["戴乌帽子的两人","头戴黑色乌帽子的男人们：穿绿衣的伸手向棋盘，穿红衣的在旁观看。"],["将棋盘","格子很大的棋盘，与围棋盘相比，格数少得多。"],["大笑的对手","光头的僧人拈起棋子，对面的男人抱着头大笑。是谁刚占了上风吗？"],["猴子","廊下的一端，好像是一只穿红衣的猴子。"],["马","扬起前蹄的黑马，被绳子拴着。"]]},"goryeo":{"title":"下棋人物纹镶嵌青瓷注子","artist":"作者不详","date":"13世纪","place":"朝鲜半岛（高丽）","game":"围棋（韩语“巴督”）","medium":"青瓷，白土与黑土镶嵌","size":"高20.4厘米，径14.3厘米","credit":"约翰·L·塞弗伦斯捐赠，1917年","p":["这是一件高丽青瓷注子（有流和把手的酒器）。在胎上刻线、填入白土和黑土，再施釉烧成的“镶嵌”是高丽陶工的拿手技法。圆形的框里，柳树下坐着的两人以白色浮现出来。","两人之间有一个棋盘，美术馆认为这一场面可与下围棋（韩语称“巴督”）的图像相比。琴、棋、书、画“四艺”被视为文人应有的修养，他们风雅的聚会也成了工艺品上的图案。描绘人物的高丽镶嵌青瓷十分罕见。"],"spots":[["棋盘","两人之间的棋盘，用白土表现为方形。"],["左边的人","面向棋盘坐着的人。"],["右边的人","坐在对面的对手。"],["柳","垂在两人头上的柳枝，用黑土描绘。"],["云纹框","圆框四周环绕着卷云般的纹样。"],["开片","釉面细密的裂纹。烧成后冷却时，因胎与釉收缩程度不同而产生。"]]},"kangra":{"title":"露台上玩乔帕尔的二人","artist":"作者不详","date":"约1790—1800年","place":"印度（帕哈里，康格拉画派）","game":"乔帕尔","medium":"素描，赭红起稿","size":"19.4×13.2厘米","credit":"爱德华·L·惠特莫尔基金购藏，1936年","p":["这是喜马拉雅山麓帕哈里地区康格拉画家的素描。先用红线（赭红颜料）起稿，再用黑线修整。因为没有上色，人物和器物的线条一目了然。","一男一女坐在露台上，隔着十字形的棋盘玩乔帕尔。乔帕尔与帕奇西使用同样的十字盘，是印度自古流行的竞走游戏，掷长骰（帕萨）来走棋。棋盘上还没有画出格子。侍女们在两人身旁侍候。"],"spots":[["十字棋盘","放在地上的十字形棋盘，格子还没画。"],["女子","掌心朝上的女子，是要掷骰子吗？"],["男子","缠着带羽饰头巾的男子，把手伸向棋盘。"],["左边的侍女","她拿着小瓶，伸出一块布。"],["右边的侍女","她拿着长柄的器具和一个小容器。"],["红色底稿","头巾周围，黑线下面露出红色的底稿。"]]},"vuillard":{"title":"跳棋对局（选自《风景与室内》）","artist":"爱德华·维亚尔","date":"1899年","place":"法国","game":"西洋跳棋","medium":"彩色石版画（第3版次）；奥古斯特·克洛印制，安布鲁瓦兹·沃拉尔出版","size":"画面33×25.7厘米（纸张38×30.8厘米）","credit":"汉纳基金捐赠，1951年","p":["画商安布鲁瓦兹·沃拉尔也是重要的版画出版人。1895年他请博纳尔创作了12幅彩色石版画的画集，此后又接连出版多部画集，维亚尔的《风景与室内》便是其中之一，由名印刷师奥古斯特·克洛印制。","博纳尔和维亚尔同属“纳比派”（希伯来语意为“先知”），他们追求以形与色本身来表达情感的新艺术，喜欢描绘都市生活与家庭日常。在满是花纹的房间里，两个男人隔着跳棋盘对弈，一位女子站着观战。法语把跳棋叫作“dames”，左下角的铅笔字可读作“partie de dames”，即“一局跳棋”。"],"spots":[["棋盘","小小的方格棋盘，上面摆着棋子。"],["左边的男人","留胡子的男人把手伸向棋盘。"],["右边的男人","对手坐在扶手椅上低头看棋，被站着的女子挡住了一半。"],["站着的女子","她手托下巴，关注着胜负。"],["灯","墙边的灯。壁纸和椅子的布面都布满花纹。"],["铅笔字","左下角用铅笔写着“partie de dames”（一局跳棋）。"]]},"talbot":{"title":"下国际象棋的人（早期照片）","artist":"传为威廉·亨利·福克斯·塔尔博特","date":"约1843—47年","place":"英国","game":"国际象棋","medium":"盐纸印相","size":"19.9×15厘米","credit":"埃弗里特·科夫勒夫妇出资购藏","p":["塔尔博特发明的“负片—正片法”能用一张底片印出任意多张照片，直到数码时代都是摄影的基础。他早期的实验既体现了对科学的兴趣，也体现了艺术上的抱负。研究证实，他拍过10张以上下棋人的照片。","不过这一张可能并非他本人所摄：同一场景的照片都没有签名，纸张也与他惯用的不同。照片中的人大概是摄影师安托万·克洛代和塔尔博特的助手尼古拉斯·亨尼曼。新的研究认为，这些照片在克洛代的工作室拍摄，后归亨尼曼所有，再由他作为抵债的一部分交给塔尔博特（美术馆解说）。"],"spots":[["棋盘","桌上的棋盘，棋子排成一列列。"],["戴高礼帽的男人","戴着帽子，伸手去拿棋子。"],["沉思的男人","手托下巴，盯着棋盘的对手。"],["幕布","后面垂下的幕布，大概是拍照用的背景。"],["另一顶帽子","右边的台子上还放着一顶高礼帽。"]]},"pvl":{"title":"掷骰子的男人们","artist":"PVL大师","date":"约1520年","place":"尼德兰","game":"骰子","medium":"纸本铜版画（雕刻凹版）","size":"9.4×9.4厘米（圆形）","credit":"查尔斯·哈克与赫恩家族信托收藏，2023年购藏","p":["这是16世纪初活跃于尼德兰、姓名不详的铜版画家的作品。左下角刻着“PVL”的组合字母，因此人称“PVL大师”。在只有手掌大小的圆形画面上，用密密麻麻的细线刻画出房间的纵深和衣服的质感。","桌上有两颗骰子。探身的男人和毛皮领子的青年伸着手指争论着什么，也许是在争点数。后面的女人们探头观看，桌下放着酒壶。骰子自古与赌博相连，屡次遭到禁止。"],"spots":[["骰子","桌上滚动的两颗骰子。"],["指着的手","两人的手指在桌上碰到一起。是在争点数吗？"],["宽檐帽的男人","探身向前的男人。开衩的蓬袖是当时流行的服饰。"],["毛皮领子的青年","戴大帽子、穿毛皮领子的青年。"],["观看的女人们","从后面探头看赌局的女人们。"],["组合字母","左下的“PVL”，是这位画家名字的唯一线索。"]]},"kiyohiro":{"title":"玩双六的人","artist":"鸟居清广","date":"约1750年","place":"日本（江户时代）","game":"盘双六","medium":"红摺绘（套色木版，大判），版元鳞形屋","size":"43.5×29.3厘米","credit":"克拉伦斯·白金汉收藏","p":["鸟居清广是约1737年至1776年活跃的浮世绘画师。这幅是“红摺绘”，用红（胭脂）和绿等少数几块色版套印，属于1765年多色“锦绘”诞生之前的配色。","在黑色台座的棋盘上玩的是盘双六：两人掷骰子，移动白子和黑子，先把自己的棋子全部走出的一方获胜。它与西方的双陆（西洋双陆棋）同属一类，浮世绘中常常画女性玩盘双六的情景。后面的女子一边吸着烟管，一边观战。"],"spots":[["棋盘","带台座的双六盘，摆着白子和黑子。"],["左边的人","伸手移动棋子。"],["右边的女子","俯身看着棋子的对手。"],["拿烟管的女子","在后面吸着长烟管，观看胜负。"],["举起的手","右边的女子举着一个黑色的小东西，是摇骰子的筒吗？"],["署名","“鸟居清广笔”的署名和版元鳞形屋的印。"]]},"ingram":{"title":"中国象棋","artist":"约翰·英格拉姆（据布歇原画）","date":"1741—63年","place":"法国（巴黎）","game":"象棋","medium":"蚀刻与雕刻凹版","size":"纸张39.4×27.7厘米（版面24.5×16.4厘米）","credit":"伊莱沙·惠特尔西收藏，1966年","p":["这是伦敦出生的版画家约翰·英格拉姆根据法国画家弗朗索瓦·布歇的素描刻制的铜版画。英格拉姆移居巴黎，在1741年至1763年间把布歇的“中国风”（欧洲人想象中的中国）作品一幅幅刻成版画。下方题字为“LE JEU D'ECHETS CHINOIS”（中国象棋）。","高髻的女子在膝上的棋盘上走棋，一个小孩在旁观看。画中的游戏被认为是中国象棋，但真正的象棋棋子都是扁平的圆片，这里却有高高的棋子和小小的方块。椰子树和坐在罐上的人像，与其说是真实的中国，不如说是当时欧洲梦想中的远方国度。"],"spots":[["棋盘与棋子","膝上的棋盘，摆着高棋子和方棋子。真正的象棋棋子是扁平圆片。"],["拈子的手","女子的右手在走棋。"],["托腮","左手托着下巴，低头看棋盘。"],["观看的孩子","站在棋盘旁观看对局的孩子。"],["罐上的人像","盘腿坐在大罐顶上的人像。"],["题字与署名","“布歇画”“英格拉姆刻”的署名和题字“LE JEU D'ECHETS CHINOIS”。"]]},"posada":{"title":"鹅棋","artist":"何塞·瓜达卢佩·波萨达","date":"1909年","place":"墨西哥","game":"鹅棋","medium":"锌版凸版，纸本","size":"29.3×39.4厘米","credit":"威廉·麦卡林·麦基纪念基金","p":["这是以骷髅画“卡拉韦拉”闻名的墨西哥版画家波萨达，为墨西哥城出版商安东尼奥·巴内加斯·阿罗约制作的、用来玩的单张印刷品。左下的飘带上写着“JUEGO DE LA OCA”（鹅棋），棋路从第1格起盘旋到中心的63。","中央印着玩法（EXPLICACION）：第一次掷出5和4就到26，掷出6和3就到53。停在鹅（鸟）格就按同样点数再走一次；19的客栈（Venta）休息两轮；31的井（Poso）和52的监狱（Carcel）要等别人来才能出去；42的迷宫退回39；58的死亡（Muerte）回到起点；必须正好走到63才算赢。停在某些格还要付赌注，这也是一种赌博游戏。"],"spots":[["玩法","中央的“EXPLICACION”，写着各格的规则和付赌注的方法。"],["第1格","起点。从这里盘旋着走向中心。"],["井（31）","像喷泉一样的井。掉进去就要等别人来才能出去。"],["死亡（58）","骷髅格。停在这里就回到起点。"],["题字飘带","左下飘带上写着“JUEGO DE LA OCA”，下面孩子们在玩耍。"],["出版商的名字","女神手中的飘带写着“IMPRENTA DE A. VANEGAS ARROYO”，出版过许多波萨达版画的出版商。"]]},"jintile":{"title":"女子对弈画像砖","artist":"作者不详","date":"13世纪","place":"中国（金）","game":"棋戏（应为围棋）","medium":"陶（模制浮雕）","size":"高27.3厘米，宽24.8厘米，厚5.4厘米","credit":"亚洲艺术之友捐款购藏，2002年","p":["这是统治中国北方的女真王朝——金（1115—1234年）时期烧制的浮雕砖。开花的树下，两位女子在台上相对而坐，中间放着一个棋盘。","棋盘上刻着细密的格子，应是在下围棋。右边的女子探身指着棋盘，左边的女子看着。金代北方的墓葬中，常见以表现日常生活的浮雕砖装饰墓壁，这块砖大概也出自这样的墓葬。"],"spots":[["棋盘","格子细密的棋盘，应为围棋盘。"],["指点的手","右边的女子指着棋盘，是在考虑下一手吗？"],["左边的女子","高髻，注视着棋盘。"],["右边的女子","探身向着棋盘。"],["花树","两人头上伸展着开花的树枝。"],["台座","两人所坐的台，腿间有波形装饰。"]]},"kyosai":{"title":"一个屁掀翻了棋局（画册选页）","artist":"河锅晓斋","date":"19世纪中后期","place":"日本（江户—明治时代）","game":"围棋","medium":"折页画册（26个对开页）之一；纸本墨笔淡彩","size":"画册（合起）28×18厘米","credit":"安妮与安东尼·多费捐赠（纪念埃文·特纳）","p":["这是活跃于幕末至明治的画家河锅晓斋（1831—1889年）画册中的一页，用迅疾奔放的墨线画在折页画册上。晓斋受过狩野派严格的训练，同时以妖怪画、戏画和讽刺画广受欢迎。","美术馆的标题就说明了一切：“一个屁掀翻了棋局”。左边戴乌帽子的男人弯下腰，右边的棋盘飞上半空，棋罐里的棋子如雨洒落，对手仰面跌倒。认真的对局被一下子毁掉——晓斋用他飞快的笔，画出了日本自古画卷中就有的“屁”的笑料。"],"spots":[["戴乌帽子的男人","弯腰撅臀的男人，大概就是祸首。"],["飞起的棋盘","画着格子的棋盘斜着飞了出去。"],["棋罐与棋子","两个棋罐翻倒，棋子倾泻而下。"],["扇子","棋盘旁一把打开的扇子也被吹飞了。"],["仰倒的对手","仰面倒地、瞪大眼睛的男人。"],["笔线","仿佛不打草稿一气呵成的有力墨线。"]]},"yokuts":{"title":"赌戏盘","artist":"约库特人织工（姓名不详）","date":"约1900年","place":"美国（加利福尼亚州邓拉普附近）","game":"胡丘伊什（核桃壳骰子）","medium":"植物纤维（盘绕编织）","size":"高5.1厘米，直径61厘米","credit":"伦纳德·S·弗洛斯海姆夫人出资购藏","p":["加利福尼亚的许多原住民都玩碰运气的游戏。这个盘用于“胡丘伊什”，一种只有女性玩的骰子游戏：把八颗核桃壳骰子掷在盘上，用小棍计分。","盘上编织的圆形图案表现的正是这个游戏本身——骰子、计分棍和游戏的人（美术馆解说）。这是一件把自己游戏的画面织在身上的游戏用具。照片中，核桃壳骰子放在盘上和盘的四周。"],"spots":[["游戏的人","沿着盘边排列的人形，是参加游戏的人。"],["计分棍","一束束短竖线，表示计分用的小棍。"],["圆形图案","小小的圆形图案，也许表示骰子？"],["核桃骰子","核桃壳做的骰子。把八颗掷在盘上。"],["三角带","深色三角相连的带子，绕盘一周。"],["中心","编织从中心盘旋而出，外面围着一圈虚线般的环。"]]},"hokkei":{"title":"牛若丸以双六胜弁庆","artist":"鱼屋北溪","date":"约1825年","place":"日本（江户时代）","game":"盘双六","medium":"摺物（色纸判套色木版）","size":"21.8×19.1厘米","credit":"海伦·C·冈索勒斯捐赠","p":["这是葛饰北斋的弟子鱼屋北溪（1780—1850年）的摺物。摺物是狂歌同好等为印上自己的诗歌而特别定制的版画，比市售浮世绘用纸更好，还用金属颜料，做工讲究。","牛若丸是英雄源义经少年时的名字，弁庆是力大无穷的僧兵。两人最有名的相遇是京都五条大桥上的决斗，而这幅摺物把较量换成了盘双六：少年从容地坐在棋盘对面，背着长刀的弁庆挠头认输。这大概是一种“见立”的戏仿。"],"spots":[["双六盘","箱形的双六盘，摆着白子和黑子。"],["挠头的弁庆","身披铠甲的弁庆输了，正在挠头。"],["牛若丸","坐在棋盘对面的少年牛若丸。"],["长刀","弁庆背着的大薙刀的刀刃。"],["狂歌","右上的诗句，大概是定制摺物的同好所作。"],["署名","右下框内北溪的署名。"]]},"vorsterman":{"title":"玩双陆的人（夜景）","artist":"卢卡斯·埃米尔·福斯特曼（据亚当·德·科斯特原画）","date":"约1630年","place":"佛兰德（安特卫普）","game":"双陆（西洋双陆棋）","medium":"雕刻凹版，象牙色纸","size":"画面25.5×34.4厘米","credit":"伯纳德·F·罗杰斯收藏","p":["亚当·德·科斯特是1630年前后安特卫普擅长烛光夜景的画家。同一时期，福斯特曼在同一座城市把当红画家的作品刻成版画。他是鲁本斯的学生，与老师失和、去英国之后，开始制作明暗强烈、更具风格化的卡拉瓦乔式版画，这幅就是一例。","昏暗的房间里，男人们围着桌上的双陆棋盘。仿照德·科斯特对光的处理，两支烛火照亮了桌边的面孔（美术馆解说）。右边抱着鲁特琴的少年望向我们。"],"spots":[["棋盘","桌上像盒子一样打开的双陆棋盘。"],["蜡烛","烛台上的蜡烛，火光照亮人们的脸。"],["抽烟斗的男人","戴宽檐帽的男人叼着烟斗看棋。"],["背对的男人","双手撑桌、探身向前的男人。"],["弹鲁特琴的少年","抱着鲁特琴、朝我们微笑的少年。"],["署名","左下“A. De Coster pi.”，右下“Vorsterman”。"]]},"zorn":{"title":"下国际象棋的人","artist":"安德斯·佐恩","date":"1891年","place":"瑞典","game":"国际象棋","medium":"蚀刻版画，象牙色直纹纸","size":"画面13.5×9.6厘米（版13.9×10厘米）","credit":"华莱士·L·德沃尔夫与查尔斯·迪林的佐恩蚀刻收藏","p":["这是瑞典艺术家安德斯·佐恩（1860—1920年）的蚀刻版画。佐恩以油画和水彩肖像闻名国际，同时也留下了大量铜版画。这块版只有手掌大小。","只靠层层叠加的快速斜线，昏暗的房间和人物就从铜版上浮现出来。前面的男人背对我们，俯身看棋盘；对面的人低着头思考下一步。棋盘上用细线画着棋子。画的是谁，没有留下记录。"],"spots":[["棋盘与棋子","下方明亮的部分是棋盘，短竖线是棋子。"],["前面的男人","背对我们、俯身看棋盘的男人。"],["对面的人","低头注视棋盘的对手。"],["暗色背景","用竖线叠出的昏暗房间深处。"],["斜线","外衣用迅速的斜线层层叠出。"],["署名","版下用铅笔签着“Zorn”。"]]},"harunobu-sugoroku":{"title":"观棋（盘双六）","artist":"铃木春信","date":"约1766年","place":"日本（江户时代）","game":"盘双六","medium":"套色木版（中判，摺物）","size":"28.5×21厘米","credit":"克拉伦斯·白金汉收藏","p":["铃木春信（1725?—1770年）是1765年前后用多块色版套印的“锦绘”诞生时的核心画师。这幅是特别印制的摺物，柔和的色彩层次体现了当时的新意。","梅花盛开的厅堂里，两位少女隔着箱形的双六盘对局，另一位站着俯看棋盘。盘上排着白子和黑子，左边的少女在走子，右边的也伸手向盘。后面的隔扇上画着瀑布和松树。"],"spots":[["双六盘","箱形的盘双六棋盘，摆着白子和黑子。"],["左边的少女","穿千纸鹤图案的和服，正在走子。"],["右边的少女","俯身伸手向棋盘的对手。"],["观棋的少女","站着俯看棋局，手持长柄器具。"],["梅","从上方伸出枝条的白梅。"],["隔扇画","画着瀑布和松树的隔扇。"]]},"kota":{"title":"科塔王吉肖尔·辛格二世礼拜克里希纳","artist":"作者不详","date":"约1825年","place":"印度（拉贾斯坦，科塔）","game":"帕奇西","medium":"纸本胶彩、银、金","size":"24.5×18.8厘米","credit":"詹姆斯·阿尔伯特与玛丽·加德纳·福特纪念基金","p":["拉贾斯坦小土邦科塔的君主（1819—1828年在位）身着普什提·马尔格派祭司的服装，献上燃着五朵火焰的灯。祭坛小龛里供奉着克里希纳与两位妃子的金属像，这尊神像只在科塔受到礼拜。","天花板上垂下许多玻璃灯，通往祭坛的台阶上摆着给克里希纳和同伴们解闷的玩具和游戏用具：黄铜大象、银牛、球，还有一块帕奇西棋盘（美术馆解说）。那块红色十字形的布就是棋盘——帕奇西作为神的玩物被供奉在这里。"],"spots":[["帕奇西棋盘","台阶上红色十字形的布，就是帕奇西棋盘。"],["大象","两头黄铜大象立在棋盘旁。"],["球","上一级台阶上的金色小球。"],["克里希纳像","小龛里供奉的克里希纳与两位妃子像。"],["君主与灯","身着祭司服的君主献上五焰灯。"],["玻璃灯","天花板上垂下的许多玻璃灯。"]]},"coyote":{"title":"郊狼棋","artist":"何塞·瓜达卢佩·波萨达的追随者","date":"年代不详","place":"墨西哥","game":"郊狼与母鸡（狐狸与鹅一类）","medium":"锌版凸版，纸本","size":"38.2×30.5厘米","credit":"威廉·麦卡林·麦基纪念基金","p":["这是和波萨达为墨西哥城民间印坊所作的作品一样、用锌版凸版印制的单张游戏纸。上方大字写着“JUEGO DEL COYOTE”（郊狼棋），四周画着偷袭鸡舍的郊狼和挥棍驱赶的人。下方的横条写着“伊尔德丰索·T·奥雷利亚纳所有”。","下方的“EXPLICACION”印着玩法：两人对弈，一方有15只母鸡，另一方只有一只郊狼。母鸡只能向前或向旁走，不能后退；郊狼可向任何方向走，若母鸡身后是空位，就跳过去把它吃掉。母鸡把郊狼围得动弹不得就赢了。这和欧洲的“狐狸与鹅”是同一类追捕游戏。"],"spots":[["郊狼的位置","中央圆圈里的郊狼头，郊狼从这里出发。"],["母鸡的位置","画着母鸡的圆圈，母鸡棋子摆在这里。"],["玩法","“EXPLICACION”，写着棋子数、走法和胜负。"],["标题","“JUEGO DEL COYOTE”——郊狼棋。"],["扑向母鸡的郊狼","左下，一只郊狼扑向母鸡。"],["挥棍的人","右上，一个人举棍驱赶郊狼。"]]},"mons":{"title":"以蒙斯（贝亨）为注的双陆，1709年","artist":"彼得·诺尔佩（制版与出版）","date":"版1623—53年，印于约1709年","place":"荷兰（阿姆斯特丹）","game":"特里克特拉克（双陆的一种）","medium":"蚀刻、雕刻凹版与活字诗","size":"纸张35.8×18.6厘米（版12.9×17.5厘米）","credit":"","p":["四个男人在桌边玩特里克特拉克。据美术馆记录，字母A至D分别是马尔伯勒公爵、巴伐利亚选帝侯、奥韦克尔克勋爵和维勒鲁瓦公爵。这是一幅讽刺版画，把1709年联军从法国手中围攻并夺取蒙斯（荷兰语称贝亨）一事，比作一场以城市为赌注的棋局。后面的房间（E）里，西班牙国王腓力五世和一位女子在一起。","版上署“诺尔佩制、出版”，但画家彼得·诺尔佩在17世纪50年代初已去世，因此这大概是在17世纪的旧版上加刻字母、配上新诗重新印刷的。下方的诗开头说，大人物的游戏无非是tiktak和verkeer（两种双陆类游戏），接着逐一挖苦各位玩家。"],"spots":[["棋盘","桌上的特里克特拉克盘——以城市为注的一局。"],["A 马尔伯勒公爵","站着俯看棋盘的人，联军的英国将领。"],["B 巴伐利亚选帝侯","摘了帽子、深陷在椅子里的人。"],["C 奥韦克尔克勋爵","戴羽饰帽子的人，荷兰军队的将领。"],["E 后面的房间","门那边的卧室里，腓力五世和一位女子。"],["诗","下方用活字印的荷兰语诗，按A至E逐一讽刺。"]]},"stembus":{"title":"投票箱——政治鹅棋","artist":"约翰·米夏埃尔·施密特·克兰斯（版画）","date":"1867年","place":"荷兰","game":"鹅棋（讽刺）","medium":"石版画","size":"66×50厘米","credit":"","p":["这是一幅做成鹅棋样式的讽刺版画，附在1867年3月2日出版的周刊《荷兰观察家》第9期里，另附一张写有玩法的单页（美术馆记录）。格子里是当时各位大臣的肖像。","起点是海牙的议会所在地比嫩霍夫，终点在棋盘中央第64格“因苏林德”（荷属东印度的雅称）：爪哇岛上吊着大臣彼得·迈耶尔的肖像画。迈耶尔由殖民大臣转任东印度总督，这一任命在政坛掀起轩然大波。比通常的63格多出一格，大概就是为了这个包袱。"],"spots":[["起点","左上的建筑，游戏从海牙的比嫩霍夫（议会）开始。"],["迈耶尔的肖像","第63格：装在画框里的彼得·迈耶尔肖像，用绳子吊在岛上。"],["因苏林德 64","中央的岛和“64”字样，这里是终点。"],["投票箱","右下的“DE STEMBUS”（投票箱），标题里的箱子。"],["大臣们","格子的窗口里排着当时大臣们的面孔。"],["公鸡","格子里的一只公鸡，讽刺的是什么尚不清楚。"]]},"koorai":{"title":"围着棋盘的朝鲜人（选自西博尔德《日本》）","artist":"詹姆斯·埃克斯莱本（石版），据“Toioske”原画","date":"1832—52年","place":"荷兰（莱顿）／朝鲜人","game":"棋戏（应为围棋）","medium":"色调石版画，手工上色","size":"纸张38×55.5厘米","credit":"F·G·瓦勒捐赠","p":["这是德国出生的医生西博尔德根据在长崎荷兰商馆期间（1823—1830年）的见闻、在莱顿出版的巨著《日本》（NIPPON）中的一幅。右上写“TAB. I”，下方写“KOORAI”（高丽），并用荷兰语和德语注明“渔夫一家”。石版由埃克斯莱本绘制，版上注明原画作者为“Toioske”。","四个男人坐在地上围着棋盘，左边一位女子牵着小孩，右边站着一个拿长棍和袋子的男人。前面地上放着一顶宽檐黑帽（笠子）。棋盘上画着格子和圆形棋子，应是在下围棋（韩语“巴督”），但记录里只写“棋戏”。"],"spots":[["棋盘","格子上放着圆形棋子，应是在下围棋。"],["黑帽","放在地上的宽檐黑帽（笠子）。"],["母与子","牵着孩子观看对局的女子。"],["站着的男人","拿着长棍和袋子站着的男人。"],["俯身的男人","穿蓝上衣的男人俯身看棋盘。"],["标题","“KOORAI”（高丽），以及荷兰语和德语的“渔夫一家”。"]]},"cairo":{"title":"咖啡馆前围着棋盘的人们（开罗）","artist":"德利耶与贝夏尔（伊波利特·德利耶、埃米尔·贝夏尔）","date":"约1869—90年","place":"埃及（开罗）","game":"棋戏（应为国际象棋）","medium":"蛋白照片","size":"10.8×16.4厘米","credit":"","p":["这是在开罗开设照相馆的法国摄影师伊波利特·德利耶和埃米尔·贝夏尔拍摄的照片。衬板上印着照相馆的名字“埃兹贝基亚花园旁”和“开罗（埃及）”。这类照片是到访埃及的旅客买来做纪念的。","男人们坐在装着格子窗的店门前的地上，围着矮架上的棋盘。棋盘上立着好几枚高高的棋子，应是国际象棋（阿拉伯语“沙特兰吉”），但美术馆记录只写着“棋戏”。为了拍照，大家都一动不动。"],"spots":[["棋盘与棋子","矮架上的棋盘，立着高棋子，应是国际象棋。"],["格子窗","装着木格子的窗户，开罗老房子常见的样式。"],["拄杖的男人","拿着手杖坐着看棋的男人。"],["篮子","放在地上的编织篮。"],["观看的孩子","从后面探看棋盘的孩子。"],["照相馆名","衬板上的“AU JARDIN DE L'ESBÉKIEH”和“CAIRE (EGYPTE)”。"]]},"vanmour":{"title":"打牌的亚美尼亚人聚会","artist":"让-巴蒂斯特·范穆尔","date":"约1720—37年","place":"奥斯曼帝国（伊斯坦布尔）","game":"纸牌","medium":"布面油画","size":"44.5×58.5厘米","credit":"","p":["生于佛兰德的画家范穆尔，1699年随法国大使来到伊斯坦布尔，此后一直住在这座城市直到去世，描绘宫廷典礼和市民生活。美术馆记录说，从衣着可以看出画中的男人是亚美尼亚人。","在一支大蜡烛的光下，男男女女围着铺红布的桌子打牌。桌上摆着发好的牌，也有人盯着手里的牌。左边角落里，一位老妇人在纺线。记录没有写是哪种牌戏。"],"spots":[["桌上的牌","铺红布的桌上放着的纸牌。"],["大蜡烛","照亮众人的一支蜡烛。"],["纺线的老妇","左边角落纺线的老妇人。"],["看牌的女子","右端盯着手牌的女子。"],["穿毛皮的男人","穿毛皮镶边外衣的男人，衣着表明是亚美尼亚人。"],["探身的人","探身向桌、手里拿牌的人。"]]},"algiers":{"title":"下棋的三个男人（阿尔及尔）","artist":"佚名","date":"1851—1900年","place":"阿尔及利亚（阿尔及尔）","game":"棋戏（应为双陆）","medium":"蛋白照片","size":"14.0×10.0厘米","credit":"","p":["这是一张作者不详的照片，照片下方手写着“Alger（阿尔及尔）”。在素色背景前摆着椅子和小桌，应是在照相馆拍的。这类拍摄北非人物的照片，是旅客和收藏家买来的。","两个男人隔着一块有边框的棋盘相对而坐，右边的人正伸手去拿棋子。棋盘上叠着圆形棋子，应是双陆（当地称“塔乌拉”等），但记录只写着“棋戏”。前面的小桌上放着咖啡用具。"],"spots":[["棋盘与棋子","有边框的棋盘上叠放着圆棋子。"],["站着看的男人","腰缠宽带、站在后面俯看棋局的男人。"],["左边的老人","头裹布巾、陷入沉思的老人。"],["右边的男人","头披白布、俯身看棋盘的男人。"],["咖啡用具","镂雕小桌上的托盘和小杯。"],["移动棋子的手","右边棋手正要拿棋子的手。"]]},"circo":{"title":"马戏游戏（Juego del Circo）","artist":"曼努埃尔·马尼利亚（推定）","date":"年代不详","place":"墨西哥","game":"用两枚骰子的赌博游戏","medium":"凸版（木口木刻或照相凸版）·黄褐色纸","size":"26.2×35.0厘米","credit":"","p":["这是一张游戏用的单页印刷品，美术馆认为是墨西哥版画家曼努埃尔·马尼利亚所作（带问号）。右下角印着出售它的版画店“埃尔·特阿特罗”的名字和地址。这类便宜的印刷品在街头出售，看来人们不剪开就直接拿来玩。","中间是马戏帐篷，四周排着马上杂技、叠罗汉、大力士等图，每格都标着2到12的数字。左上的“说明”写道：多少人、小孩也能玩；掷两枚骰子，把赌注放在点数对应的格子上，若格子里已有赌注就拿走。掷出12的人赢走全部。"],"spots":[["马戏帐篷","“JUEGO DEL CIRCO”标题和作为12号格的帐篷。"],["玩法说明","以“ESPLICACION（说明）”开头的玩法文字。"],["马上杂技","在奔马背上跳舞的艺人，6号格。"],["叠罗汉","一人站在另一人肩上，4号格。"],["大力士","举起像大炮一样重物的男人，8号格。"],["版画店名","“De venta, Estampería ‘El Teatro’”和地址。"]]},"loteria":{"title":"墨西哥罗特里亚图卡","artist":"何塞·瓜达卢佩·波萨达","date":"1880—1913年","place":"墨西哥","game":"罗特里亚（喊图配对游戏）","medium":"凸版（木口木刻或照相凸版）·黄褐色纸","size":"30.0×40.0厘米","credit":"","p":["墨西哥版画家波萨达为墨西哥城出版商安东尼奥·瓦内加斯·阿罗约画了大量插图，这家出版商印行新闻、歌曲和游戏的廉价单页。这张上也印着“JUEGO DE LOTERIA（罗特里亚游戏）”的标题和瓦内加斯·阿罗约的名字。","纸上排着38幅标有名字的小图：星星、月亮、蝎子、魔鬼、骷髅、公鸡、印刷所等。罗特里亚是类似宾果的游戏：喊牌人抽牌喊出图名，玩家若在自己的板上有这张图，就用豆子等做记号。这张纸应是剪开当牌用的。"],"spots":[["标题与出版商","“JUEGO DE LOTERIA”和瓦内加斯·阿罗约店名。"],["星星","“ESTRELLA”，左上第一幅。"],["月亮","“LUNA”，有脸的弯月。"],["死神","“MUERTE”，拿着大镰刀吹笛的骷髅。"],["采龙舌兰汁的人","“TLACHIQUERO”，收集龙舌兰汁的男人。"],["印刷所","“IMPRENTA”，操作印刷机的工匠，正是印这类单页的地方。"]]},"jeupol":{"title":"“波兰棋”即国际跳棋棋盘","artist":"佚名","date":"1833—1900年","place":"比利时或荷兰","game":"国际跳棋（10×10格）","medium":"木刻，活字印刷文字","size":"32.2×39.6厘米","credit":"","p":["这张单页上方印着法语和荷兰语的标题“JEU POLONAIS OF DAMSPEL”。“波兰棋”是法国对10×10格跳棋的称呼。右上角印着出版商的编号“n. 106”。","正如美术馆记录所说，盘上黑白各50格、共100格，左右有装饰边。没有印棋子，所以应是用豆子或纽扣当棋子、直接在纸上下的廉价棋盘。纸上还留着折痕。"],"spots":[["标题","“JEU POLONAIS OF DAMSPEL”字样。"],["编号","出版商编号“n. 106”。"],["左边饰","竖排圆形花纹的边饰。"],["右边饰","与左边相同的花纹。"],["100个格子","10×10的棋盘，黑格用细线刻成。"],["折痕","纸上留下的折痕，或许曾折起来随身携带。"]]},"dkaart":{"title":"可剪下的多米诺骨牌与纸牌","artist":"佚名（布雷波尔斯版）","date":"1800—1833年","place":"比利时（蒂伦豪特）","game":"多米诺与纸牌","medium":"木刻（蓝、红、黄着色），活字印刷文字","size":"34.3×41.9厘米","credit":"","p":["据美术馆记录，这张纸印着可剪下使用的32张纸牌和28枚多米诺骨牌，是出版商布雷波尔斯目录中的第114号，下方印着零售商“D. 普韦尔斯（贝亨奥普佐姆）”。标题用荷兰语和法语并列。","左边从0-0到6-6的28枚骨牌排成三角形。右边是各花色7到10加人头牌和A，共32张，是玩皮克牌等用的一副牌。因为没有被剪开，我们能看到它刚印好时的样子。"],"spots":[["标题","“DOMINO EN KAARTSPEL”字样。"],["双白","三角形顶端没有点的0-0骨牌。"],["双六","最下排右端、最大的6-6。"],["黑桃A","左列从上数第二张。"],["人头牌","用红、蓝、黄上色的国王牌。"],["零售商名","下方的“D. POUWELS, Bergen-op-Zoom”。"]]},"apen":{"title":"玩双陆的两只猴子","artist":"奎林·布尔（据达维德·特尼尔斯原画）","date":"1635—1690年","place":"佛兰德","game":"特里克特拉克（双陆的一种）","medium":"蚀刻版画","size":"11.0×14.5厘米","credit":"","p":["这是让猴子模仿人类行为的“猴戏图”系列（扉页加六幅）中的一幅。左下写着“D. 特尼尔斯原作并出版，特许”，由奎林·布尔把佛兰德画家特尼尔斯的构图刻成版画。","正如美术馆记录所说，两只猴子坐在地上，中间是一副特里克特拉克棋盘。左边的猴子用玻璃杯喝酒，右边的猴子戴着插公鸡羽毛的帽子，伸手去拿棋子。这应是在嘲笑沉迷酒和赌博的人。"],"spots":[["棋盘","放在地上的折叠式棋盘，能看到三角形格和棋子。"],["左边的猴子","穿着外衣坐在棋盘前的猴子。"],["酒杯","左边猴子举着的玻璃杯。"],["羽毛帽","右边猴子帽子上插的公鸡羽毛。"],["酒壶","左边猴子脚边的壶。"],["题铭","“D Teniers in et excud cum privilegio”字样。"]]},"dstereo":{"title":"在桌边玩多米诺的男人们（立体照片）","artist":"佚名","date":"1850—1880年","place":"不详（荷兰语题字）","game":"多米诺骨牌","medium":"蛋白照片（立体照片）","size":"8.5×17.0厘米","credit":"","p":["这是左右并排两张几乎相同照片的立体照片。用专门的观看镜（立体镜）看，就会合成一个有纵深的立体画面。左边手写着“Het dominospel（多米诺游戏）”。","人们在建筑前的阳光下摆了张桌子，穿衬衫的男人们手里拿着骨牌。两人站着看牌局，右边的人戴着白帽子。因为大家必须保持不动，这个场面应是为拍照布置的。"],"spots":[["桌上的骨牌","手里扣着的多米诺骨牌。"],["戴白帽的男人","坐在右边拿着骨牌的男人。"],["系围巾的男人","脖子上系着围巾、站着俯看的男人。"],["左边的男人","支着胳膊看牌的年轻人。"],["题字","左边手写的“Het dominospel.”。"],["另一张","右边的照片，从稍微错开的位置拍摄，两张合起来看就是立体的。"]]},"gojo":{"title":"下棋的两位女子","artist":"佚名","date":"1870—1891年","place":"日本","game":"应为围棋","medium":"手工上色蛋白照片","size":"9.0×13.5厘米","credit":"","p":["这是在黑白照片上用毛笔上色的手工上色照片。这类照片由横滨等地的照相馆制作，作为卖给外国人的纪念品。这张原贴在一本马尼拉旅行的相册里。","以壁龛式的陈设和屏风为背景，两位女子隔着有脚的棋盘对坐，左边的女子正在落子。棋盘上有黑白棋子，应是围棋，但美术馆记录写的是“棋戏”。前面的托盘里摆着点心和器皿。"],"spots":[["棋盘与棋子","带脚的厚棋盘上有黑白棋子。"],["落子的手","左边女子正在落子。"],["左边的女子","回头看向我们的女子，腰带打着大结。"],["右边的女子","穿条纹和服的女子，手放在棋盘边。"],["托盘与器皿","前面摆着的点心和茶杯。"],["插花","身后架子上的花瓶。"]]},"meade":{"title":"下国际象棋的两个男人","artist":"查尔斯·理查德·米德、亨利·威廉·马修·米德","date":"1852年","place":"美国","game":"国际象棋","medium":"达盖尔银版照片","size":"6.9×8.3厘米","credit":"","p":["这是生于英国、移居美国的米德兄弟照相馆拍摄的达盖尔银版照片。达盖尔银版是在镀银铜板上直接成像的照片，无法加印，每张都是孤品，因此装在带金色框的小皮盒里。","两个年轻人隔着小架子上的棋盘对坐，左边的人手指搭在棋子上。右边的人手按胸口，盯着棋盘。因为必须长时间不动，这步棋应是摆出来的姿势。"],"spots":[["棋盘","铺花布的架子上的棋盘和白棋子。"],["左边的男人","手指搭在棋子上的人。"],["右边的男人","低头看棋盘的人。"],["按在胸口的手","右边那人若有所思的手。"],["桌布","铺着花布的小架子。"],["金色框","保护影像的金色框和盒子。"]]},"weiqidai":{"title":"仙人弈棋山水图","artist":"传戴进","date":"明代，15—16世纪","place":"中国","game":"围棋","medium":"立轴，绢本设色","size":"175.2×106.7厘米","credit":"","p":["这是一幅传为明代画家戴进（约1388—1462年）所作的大立轴。戴进是浙江人，以笔力雄健的山水著称，后被奉为“浙派”之祖。高耸的山崖和大树下，人物画得很小。","树荫下的地上，两位仙人隔着画有纵横线的棋盘对坐，旁边放着果盘和器皿。左边蹲着的人物，让人想起在山中看仙人下棋、斧柄都烂掉了的樵夫故事（“烂柯”），但美术馆的题目只说是“仙人弈棋”。"],"spots":[["棋盘","有边框的棋盘，画着细密的格子。"],["长须仙人","长须的仙人，悠然坐着看棋盘。"],["青巾仙人","俯身向棋盘的仙人，膝边有棋子罐。"],["蹲着的人","在左边探看棋局的人，或许就是烂柯故事里的樵夫。"],["果盘与器皿","棋盘那边的盘子和壶。"],["款印","右上的署款和两方朱印。"]]},"reise":{"title":"环游世界之旅（水路与陆路）","artist":"佚名","date":"19世纪","place":"应为德语地区","game":"掷骰赛跑游戏（下注玩）","medium":"石版画","size":"42.5×33.7厘米","credit":"","p":["这是一张游戏用单页，用德语题为“环游世界之旅，水路与陆路——新颖有趣的骰子游戏”。圆形棋盘上排着1到41格，画着热气球、帆船、轮船、火车和各国人物等。右下角编号“No. 107”。","下方用德、英、荷、法四种语言印着玩法：每人先付15马克到公共的“旅费钱袋”，然后轮流掷一枚骰子移动记号。停在大图格上赢2马克，停在没有图的格子罚2马克，正好到达41的人拿走剩下的全部。"],"spots":[["41：驿马车","中央的终点，载客的驿马车和车夫。"],["1：英国人","起点格，戴高礼帽的“Engländer”。"],["热气球","飘在空中的热气球格。"],["帆船","张满帆的船。"],["火车","冒着烟的蒸汽机车。"],["玩法","用四种语言印的规则。"]]},"huchten":{"title":"以命相赌的骰子","artist":"扬·范·胡赫滕堡","date":"1680—1720年","place":"荷兰","game":"骰子","medium":"布面油画","size":"67.5×76.0厘米","credit":"","p":["这是以战争画闻名的荷兰画家胡赫滕堡（1647—1733年）的作品，左下有签名。美术馆的标题是“以命相赌的骰子游戏”。要塞外，两名囚犯在鼓面上掷骰子，军官和士兵围在四周。","右后方立着绞刑架，左边的要塞墙上也有士兵在看。这应是被判罪的士兵用骰子决定谁受刑的场面。一名囚犯指着鼓，另一名跪着看点数。"],"spots":[["鼓与骰子","代替桌子的鼓，骰子就掷在上面。"],["指着鼓的囚犯","站着指向鼓面的囚犯。"],["跪着的囚犯","穿白衬衫、俯身在鼓上的囚犯。"],["马上的军官","戴帽子、从马上俯视的军官。"],["绞刑架","右上方的绞刑架。"],["墙上的士兵","在要塞墙上观看的士兵们。"]]},"vertu":{"title":"美德游戏（Spel der Deugd）","artist":"扬·赫里茨·菲瑟（J. 福尔曼设计）","date":"1798年","place":"荷兰","game":"两枚骰子的赌博游戏","medium":"雕版、蚀刻、活字印刷","size":"56.9×38.0厘米","credit":"","p":["这是一张用荷兰语和法语题为“美德游戏”的大幅游戏版画。在列柱神殿中央坐着“美德”，左边站着“繁荣”，右边是“贫穷”；柱子上挂着诚实、感恩、爱等美德的圆章，下面的台座画着贪婪、骄傲、懒惰等恶行。","据下方规则，可用两枚骰子玩，也可抽签玩。用骰子时，大家共下注63，按太阳运行的方向轮流掷。每种点数对应一种美德或恶行：双六“美德”拿走全部赌注，双一“恶行”要付8。图下的“T”是拿的数，“B”是付的数。"],"spots":[["标题","山墙上的“SPEL DER DEUGD”。"],["美德","中央宝座上的“美德（LA VERTU）”，双六拿走全部。"],["繁荣","拿着丰饶角的“繁荣”。"],["恶行","双一的“恶行（LE VICE）”，举杯的孩子。"],["贪婪","台座上的“贪婪（L’AVARICE）”，下面的“B”和骰点是要付的数。"],["玩法","下方密密印着的规则。"]]},"charros":{"title":"走私的牛仔（骰子游戏）","artist":"何塞·瓜达卢佩·波萨达","date":"年代不详","place":"墨西哥","game":"掷骰赛跑游戏（三枚骰子）","medium":"石版画","size":"29.9×40.4厘米","credit":"","p":["这是一张波萨达绘图的赛跑游戏，题为“LOS CHARROS CONTRABANDISTAS（走私的查罗）／JUEGO DE DADOS（骰子游戏）”。下方印着出版商“A. 瓦内加斯·阿罗约印刷所，墨西哥”，右下有波萨达的签名。查罗是墨西哥的骑马牧人，四角画着戴宽边帽策马奔驰的他们。","用绳纹框起的圆格在盘面上蜿蜒，里面画着动物、人物、火车等。右上的“说明”说要用三枚骰子：第一次就掷出三个一点即获胜，落在骷髅格就输；鹿格可从彩池中拿取，强盗格要付钱，狮子格要停住直到有人来。"],"spots":[["标题","“LOS CHARROS CONTRABANDISTAS／JUEGO DE DADOS”。"],["说明","以“EXPLICACION”开头的玩法。"],["玩游戏的人","左下围着桌子玩棋盘的人们。"],["骰子","盘面中间画的三枚骰子。"],["马上的查罗","挥舞套索、策马奔驰的查罗。"],["出版商名","“IMPRENTA DE A. VANEGAS ARROYO, MÉXICO”。"]]},"snuffwq":{"title":"绘对弈人物鼻烟壶","artist":"中国","date":"清代道光年间（1820—50年），道光款","place":"中国","game":"围棋","medium":"瓷胎粉彩","size":"高5.7厘米","credit":"","p":["这是清代用来装鼻烟随身携带的小瓶。美术馆记录说有道光款，年代为1820—50年。在约六厘米高的白瓷瓶身上，用釉上彩画着山景和人物。","洞穴般的山石旁，两位老人隔着放在蓝色台子上的棋盘对坐，左边的老人正要落子。他身后有个拄杖的孩子在看。题材应是让人想起看仙人下棋的樵夫故事。"],"spots":[["棋盘","蓝色台子上画着细格的棋盘。"],["长须老人","穿紫衣、伸手向棋盘的老人。"],["对面的老人","坐在右边、举手看棋的老人。"],["拄杖的孩子","在后面拄杖观看的孩子。"],["山洞","身后洞穴般的山石。"],["瓶塞","绿色的瓶塞。"]]},"ostade":{"title":"酒馆里玩特里克特拉克的人们","artist":"阿德里安·范·奥斯塔德","date":"1653年","place":"荷兰（哈勒姆）","game":"特里克特拉克（双陆的一种）","medium":"蚀刻版画","size":"8.5×7.4厘米","credit":"","p":["这是以描绘农民生活著称的哈勒姆画家奥斯塔德的一幅巴掌大小的蚀刻版画，下方刻着“A. ostade”的签名。昏暗的酒馆里，铅框窗户透进的光照着人们。","左边桌旁两人隔着特里克特拉克棋盘对坐，后面一人探头看着。右边一个男人靠墙坐着，手里拿着杯子。地上还倒着大酒壶，像是酒馆里悠闲的午后。"],"spots":[["棋盘","桌上的特里克特拉克棋盘。"],["左边的棋手","戴帽子、面对棋盘的男人。"],["右边的棋手","俯身在棋盘上的男人。"],["探头看的人","站在后面看棋的男人。"],["休息的人","靠墙坐着、手拿杯子的男人。"],["铅框窗","菱形格子的窗，光从这里进来。"]]},"lenain":{"title":"掷骰子的人们","artist":"马蒂厄·勒南的追随者","date":"1630—1680年","place":"法国","game":"骰子","medium":"布面油画","size":"92.8×119.7厘米","credit":"","p":["这是一位效仿法国勒南兄弟中最小的马蒂厄画风的画家所作。据美术馆说，加布里埃尔·德·圣奥班画过同样构图的速写，藏于巴黎国家图书馆。","户外的小圆桌旁，三个男人在掷骰子；两人在旁观看，左边的人抱着酒瓶。右边站着两只细长的猎犬，开口外是广阔的原野。桌上的白色小东西就是骰子。"],"spots":[["桌上的骰子","滚在圆桌上的骰子。"],["戴浅色帽的男人","坐着伸手查看点数的男人。"],["黑衣男子","手叉腰站着的年轻人。"],["后面的少年","在桌后看着的少年。"],["抱瓶的男人","左边抱着瓶子、朝我们笑的男人。"],["两只猎犬","右前方细长的狗。"]]},"tunisie":{"title":"阿拉伯咖啡馆前的纸牌游戏（安特卫普世博会突尼斯馆）","artist":"佚名（Ch. 伯恩赫夫特印制）","date":"1894年","place":"比利时（安特卫普）","game":"纸牌","medium":"珂罗版","size":"15.4×21.6厘米","credit":"","p":["这是收录1894年安特卫普世界博览会照片49幅的一套图版之一，上方印着“EXPOSITION UNIVERSELLE D’ANVERS 1894”，下方印着“突尼斯——阿拉伯咖啡馆前的纸牌游戏”。印制者是卢森堡宫廷摄影师伯恩赫夫特。","照片摄于为世博会突尼斯区修建的、有圆顶和塔楼的广场。穿突尼斯服装的男人们围着镶瓷砖的小桌打牌，有人在抽水烟，旁边还有放茶杯的托盘。右边坐着穿西装的观众，这应是展示远方生活的展览。"],"spots":[["牌桌","围着镶瓷砖小桌拿着牌的男人们。"],["水烟","左边男人含着的水烟管。"],["穿西装的观众","坐在右边的西装男子，应是世博会的游客。"],["茶杯托盘","桌下的小茶杯。"],["圆顶与塔","背景中为世博会建造的突尼斯风格建筑。"],["标题","“TUNISIE”和“PARTIE DE CARTES DEVANT UN CAFÉ ARABE”。"]]},"laghouat":{"title":"拉格瓦特附近的卡伊德们","artist":"佚名","date":"1880—1890年","place":"阿尔及利亚（拉格瓦特附近）","game":"应为多米诺","medium":"蛋白照片","size":"20.9×27.0厘米","credit":"","p":["这张照片题为“阿尔及利亚人——拉格瓦特附近的卡伊德们”，贴在相册里，印有编号“239”。卡伊德是法国统治下阿尔及利亚地方首领的称呼。","穿白袍的男人们坐在土墙前的席子上，在矮桌上摆着长条形的牌。从摆法看应是多米诺，但美术馆记录只写着“游戏”。前面放着茶盘和脱下的鞋子。"],"spots":[["矮桌上的牌","在桌上排成一列的长条牌。"],["茶盘","前面托盘里的茶杯和壶。"],["脱下的鞋","放在席子外的鞋。"],["后面站着的人","靠墙站着看的人。"],["土墙","背后粗糙的土墙。"],["席子","男人们坐着的编织席。"]]},"hangong":{"title":"汉宫春晓图（局部）","artist":"仇英（摹本）","date":"清代（1644—1911年）","place":"中国","game":"围棋","medium":"手卷，绢本设色","size":"36.2×454.4厘米（全卷）","credit":"","p":["这是清代临摹明代画家仇英（1494—1552年）构图的手卷的一部分，全卷长四米半以上。春日的宫苑里，宫女、少女和侍女们荡秋千、游戏、赏牡丹、奏乐、抚琴、喂鹦鹉和鱼，画面由右向左展开。","这一段里，栏杆后的两位女子隔着棋盘对坐，其他人探身观看。前面是放着太湖石的莲花形石盆，侍女们抱着乐器和包裹走过。正如美术馆所说，这幅画把深宫女子的生活画得十分理想化。"],"spots":[["棋盘","栏杆后桌上的围棋盘。"],["落子的女子","伸手向棋盘的淡紫衣女子。"],["观棋的女子们","俯身看棋局的女子们。"],["执团扇的女子","柱间拿着团扇的女子。"],["太湖石","安放在莲花形盆里的青色奇石。"],["抱乐器的侍女","抱着应是琵琶的乐器行走的侍女。"]]},"homerbg":{"title":"双陆","artist":"温斯洛·霍默","date":"约1877年","place":"美国","game":"双陆（西洋双陆）","medium":"木口木刻","size":"","credit":"","p":["这是根据美国画家温斯洛·霍默（1836—1910年）的画刻成的木口木刻。霍默年轻时当过杂志插画家，为这类版画画过许多画。下方印着“396.—BACKGAMMON.—WINSLOW HOMER.”，应是书或杂志中带编号的一页。","两位女子在有装饰的沙发上相对而坐，在搭在膝上的棋盘上玩西洋双陆。棋盘上有一个白色圆形物，是什么并不清楚。长裙的褶子和沙发卷曲的扶手都用细线刻成。"],"spots":[["棋盘","搭在两人膝上的棋盘。"],["左边的女子","挽着头发、伸手向棋盘的女子。"],["右边的女子","探身看棋盘的女子。"],["沙发扶手","卷涡形的扶手。"],["裙子","用细线刻出的长裙褶子。"],["标题","下方的“396.—BACKGAMMON.—WINSLOW HOMER.”。"]]},"chessst":{"title":"下国际象棋的男女（立体照片）","artist":"佚名","date":"1852—1858年","place":"不详","game":"国际象棋","medium":"立体照片（上色）","size":"8.3×16.5厘米","credit":"","p":["这是英语称为“The Chess Players（下棋的人）”的一对立体照片。用立体镜观看，棋盘和棋子仿佛浮到眼前。黑白照片上给红色帷幕和黄色衣裙上了颜色。","穿黄衣的女子手搭在棋子上，对面的男子背对着我们盯着棋盘。棋盘上有红白两色棋子，看似正在对局，但应是照相馆里布置的场面。19世纪中叶，这类家庭情景的立体照片销售很广。"],"spots":[["棋盘与棋子","方格棋盘上的红白棋子。"],["移动棋子的手","女子把手搭在棋子上。"],["女子","白领黄衣的女子，低头看棋盘。"],["男子","背对我们坐着的男子。"],["红色帷幕","背景中上了色的帷幕。"],["另一张","右边的照片，两张用立体镜看就有纵深。"]]},"corrida":{"title":"斗牛骰子游戏（Corrida de Toros）","artist":"何塞·瓜达卢佩·波萨达","date":"1898年","place":"墨西哥","game":"掷骰赛跑游戏（两枚骰子，下注）","medium":"照相凸版·布纹纸","size":"40.4×30.0厘米","credit":"","p":["这是波萨达绘图的赛跑游戏，题为“CORRIDA DE TOROS（斗牛）”。格子排成螺旋，从外圈的1号向中心，依次画着斗牛的招式和场面。中心是斗牛场建筑，下方印着安东尼奥·瓦内加斯·阿罗约印刷所的名字。","据下方的“说明”，两人以上各出赌注，掷两枚骰子前进。例如5号“撑竿跳”前进到10，12号“长矛手被牛顶”要付钱并停走，28号“胸前过牛”要从头开始。到达32号“拖走公牛”的人拿走全部赌注。"],"spots":[["标题","“CORRIDA DE TOROS”字样。"],["斗牛场","螺旋中心的斗牛场建筑。"],["1号格","螺旋入口的起点格。"],["牛头","右上角有角的牛头。"],["斗牛士","左下的斗牛士肖像。"],["说明","下方的“EXPLICACION”文字。"]]},"ambrocards":{"title":"打牌的三个男人","artist":"佚名（美国）","date":"1865年","place":"美国","game":"纸牌","medium":"玻璃底片照片（安布罗式）","size":"14.0×11.0厘米","credit":"","p":["安布罗式照片是把拍在玻璃板上的薄负片背面涂黑，使它看起来像正片的照片。它比达盖尔银版便宜，在1850—60年代的美国很流行。这张装在镀金框里，放在衬红天鹅绒的盒子中。","素色背景前，三个男人围着小桌，手里拿着牌。左边的人戴圆顶礼帽，右边的人戴便帽，两人都叼着雪茄；中间穿深色外套的人看着我们。应是为了拍照，摆出牌局进行中的姿势。"],"spots":[["手牌","在桌上拿着牌的手。"],["戴礼帽的男人","左边叼雪茄的人。"],["中间的男人","穿深色外套、看着我们的人。"],["戴便帽的男人","右边叼雪茄的人。"],["镀金框","围着影像的压花镀金框。"],["盒子","衬红天鹅绒的盒子。"]]},"morphy":{"title":"国际象棋冠军保罗·墨菲","artist":"温斯洛·霍默","date":"1859年","place":"美国","game":"国际象棋","medium":"木口木刻","size":"","credit":"","p":["这是下方印着“PAUL MORPHY, THE CHESS CHAMPION”的肖像木口木刻，依据当时还是年轻插画家的霍默（1836—1910年）的画刻成。墨菲（1837—1884年）是新奥尔良出身的棋手，1858—59年巡游欧洲，接连击败一流高手，载誉回国。","年轻的墨菲坐在椅子上，左手放在棋盘边，旁边立着王、车、兵等棋子。这是他归国成为话题人物的1859年之作，应是作为报刊插图印行的。"],"spots":[["棋子","棋盘上的王、车、兵等。"],["放在棋盘上的手","搭在棋盘边的左手。"],["墨菲的脸","刚过二十岁的年轻冠军。"],["领结","衣着整齐的领口。"],["膝上的手","放在膝上的右手。"],["标题","下方的“PAUL MORPHY, THE CHESS CHAMPION”。"]]},"dutton":{"title":"舍伯恩庄园客厅里的达顿一家","artist":"约翰·佐法尼","date":"约1772年","place":"英国","game":"纸牌","medium":"布面油画","size":"101.5×127.0厘米","credit":"","p":["这是生于德国、在英国成名的画家佐法尼（1733—1810年）的作品。以轻松姿态描绘家庭的“谈话画”诞生于18世纪的英国，十分流行。场景是格洛斯特郡舍伯恩庄园的客厅。","据美术馆介绍，父亲和女儿、母亲和儿子正在纸牌游戏中盘算下一手怎么出。这家人刚失去一位亲人，所以父母穿着全丧的黑衣，子女穿着轻丧的淡紫、白色和灰色。"],"spots":[["牌桌","铺绿布的桌子和纸牌。"],["父亲","穿黑衣拿着牌的父亲。"],["女儿","穿白衣看牌的女儿。"],["儿子","穿灰衣拿着牌的儿子。"],["母亲","穿黑色丧服的母亲。"],["壁炉","生着火的大理石壁炉。"]]},"whist":{"title":"圣诞节的学者们——惠斯特联合游戏","artist":"詹姆斯·布雷瑟顿（应据H. W. 班伯里原画）","date":"1773年","place":"英国","game":"惠斯特（纸牌）","medium":"蚀刻版画","size":"26.5×39.6厘米","credit":"","p":["据美术馆说，这是讽刺剑桥大学学者的漫画。左下可读出“H. W. 班伯里绘 1772”，右下是“J. 布雷瑟顿刻”，1773年由伦敦新邦德街的店出版。墙上挂着学者的方帽。","四位绅士一边打惠斯特纸牌，一边互相做鬼脸。惠斯特是两人一组对抗的游戏，标题里的“联合游戏”应是双关。后面有人在别人头上竖起手指捉弄他。旁边还有两个仆人和两只狗。"],"spots":[["桌上的牌","出在桌上的牌。"],["戴假发的学者","戴着大假发、把手牌贴在胸前的学者。"],["竖手指的人","在别人头上竖起手指的人。"],["女仆","戴帽子、端着托盘的仆人。"],["方帽","挂在墙上的大学方帽。"],["右边的狗","右下吠叫的小狗。"]]},"hey":{"title":"下棋的三个男人","artist":"保罗·海","date":"1877—1952年","place":"德国","game":"国际象棋","medium":"版画（应为蚀刻）","size":"19.3×26.0厘米","credit":"","p":["这是德国画家、插画家保罗·海（1867—1952年）的版画。三位老人凑在桌边，盯着同一副棋盘。细线层层叠加，画出深深的皱纹和白胡子。","正如美术馆记录所说，左边的人手托下巴，右边的人指间夹着雪茄，把手伸向棋子。桌子左边有两只咖啡杯、一个玻璃杯和一盒火柴。这应是在咖啡馆里下的一盘棋。"],"spots":[["棋盘","桌上的棋盘和棋子。"],["托腮的人","白胡子的老人，手托下巴沉思。"],["中间的人","探身伸手拿棋子的人。"],["右边的人","从后面探头看的人。"],["夹雪茄的手","指间夹着雪茄的手。"],["咖啡和火柴","左边的两只杯子、玻璃杯和火柴盒。"]]},"artful":{"title":"狡猾的一张牌，奶奶多输一张（红心是王牌！）","artist":"佚名","date":"1852—1863年","place":"应为英国","game":"纸牌","medium":"立体照片（上色）","size":"8.4×17.4厘米","credit":"","p":["英文标题是“The artful card, or, one too many for granny. Hearts are trumps!”。这是把用狡猾的牌赢过奶奶的滑稽小场面做成一对立体照片。从英文标题看，应是英国制作的。","圆桌边奶奶和小女孩在打牌，穿绿衣的姑娘拿着手牌，被身后的年轻男子搂着肩。“红心是王牌”应是把纸牌的红心和恋爱之心双关。有纺车和碗柜的房间，大概是照相馆的布景。"],"spots":[["姑娘的手牌","绿衣姑娘拿在胸前的牌。"],["年轻男子","从后面把手搭在姑娘肩上的男子。"],["奶奶","戴头巾、低头看牌的老妇人。"],["小女孩","笑着出牌的小女孩。"],["桌子","放着牌和小物的圆桌。"],["碗柜","玻璃门里摆着器皿的柜子。"]]},"cezcards":{"title":"玩牌者习作","artist":"保罗·塞尚","date":"1890—92年","place":"法国","game":"纸牌","medium":"水彩、铅笔·米色纸","size":"36.2×48.5厘米","credit":"","p":["1890年代，塞尚在法国南部的艾克斯画了好几幅玩牌的男人。这是为那组画作的水彩习作：戴帽子、留着小胡子的男人坐在桌前看手里的牌。","在铅笔线上薄薄叠上蓝色和灰色水彩，抓住了外衣的褶皱和身体的分量。右边和桌子远端留着未完成，只在人物周围上了色。据说模特是当地的劳动者。"],"spots":[["男人的脸","帽檐下垂着眼看牌。"],["手牌","双手拿着的纸牌。"],["桌子","只用铅笔线画的桌子。"],["椅子","左边的椅背。"],["外衣","叠着蓝灰色的衣褶。"],["未完成处","桌腿附近只留着线条。"]]},"vuillardck":{"title":"跳棋对局（《风景与室内》之一）","artist":"爱德华·维亚尔","date":"1899年","place":"法国","game":"跳棋（国际跳棋）","medium":"彩色石版画·灰象牙色纸","size":"36.9×28.5厘米","credit":"","p":["这是法国画家维亚尔的彩色石版画集《风景与室内》的第一幅，由画商安布鲁瓦兹·沃拉尔出版，石版印刷师奥古斯特·克洛印制。","在满是花纹墙纸的房间里，一位留胡子的男人对着跳棋盘，一位穿格子裙的女子站着托腮看棋。人物、墙纸和沙发都融成平涂的色块和图案，只有棋盘的黑白格清晰地浮现出来。"],"spots":[["棋盘","黑白相间的跳棋盘。"],["留胡子的男人","对着棋盘的男人。"],["站着的女子","穿格子裙、托着下巴的女子。"],["墙纸","布满卷曲线条的墙纸。"],["花纹靠垫","左下的花纹布料。"],["灯","靠墙的细长灯形。"]]},"cruikchess":{"title":"国际象棋对局","artist":"乔治·克鲁克香克（据弗雷德里克·马里亚特上尉原稿）","date":"1814年","place":"英国","game":"国际象棋","medium":"手工上色蚀刻版画","size":"23.8×34.5厘米","credit":"","p":["这是英国讽刺画家克鲁克香克根据海军军官、后来成为小说家的马里亚特的草图刻成的版画，由伦敦的汉娜·汉弗莱出版。下方印着标题“GAME of CHESS”。","点着蜡烛的桌边，两位老绅士对着棋盘。两人身后各站着一个看客：左边的把手指放在嘴边示意“安静”，右边的举着带柄眼镜凑近看棋。这应是在取笑忍不住插嘴的看客。"],"spots":[["棋盘","摆着黑白棋子的棋盘。"],["蜡烛","照亮棋盘的两支蜡烛。"],["示意安静的人","手指放在嘴边的看客。"],["拿眼镜的人","举着带柄眼镜看棋的看客。"],["睡着的狗","桌下睡觉的狗。"],["标题","下方的“GAME of CHESS”。"]]},"domino98":{"title":"在桌边玩多米诺的女子与孩子","artist":"佚名（美国）","date":"约1898年","place":"美国","game":"多米诺骨牌","medium":"蛋白照片（贴在玻璃上）","size":"40.8×51.1厘米","credit":"","p":["这是一张应出自美国照相馆的大幅照片，贴在玻璃板上装成。穿白衣的女子和卷发的小女孩隔着插着花的小桌坐着。","桌上摆着多米诺骨牌，女子正拿着一枚往下放。小女孩托着腮注视着。窗帘、装饰柜和挂画的墙，应是照相馆的布景。"],"spots":[["骨牌","桌上排着的白色骨牌。"],["小女孩","托腮看骨牌的女孩。"],["女子","穿白衣、放下骨牌的女子。"],["花","桌上花瓶里的花。"],["装饰柜","右后方华丽的柜子。"],["题字","右下的白色字样。"]]},"langkat":{"title":"在船上打牌的阿尔伯特·格拉泽和朋友们（苏门答腊，朗加特）","artist":"佚名（H. 恩斯特公司）","date":"1895—1905年","place":"印度尼西亚（苏门答腊岛，朗加特）","game":"纸牌","medium":"照片","size":"17.5×22.8厘米","credit":"","p":["这是在苏门答腊岛北部朗加特拍摄的照片。右下有照相馆“H. Ernst & Co. / Bindjey Langkat”的压印，背面手写着中间的人是阿尔伯特·格拉泽，是某位夫人的兄弟。","在搭着遮阳棚的船甲板上，三个穿白衣的男人围着桌子拿着牌。桌上放着牌和像硬币的小东西，右边男人身旁有个瓶子。白衣和遮阳棚透露出炎热地方的生活。"],"spots":[["桌上","发好的牌和像硬币的小东西。"],["格拉泽","中间展开手牌的人，背面写着他的名字。"],["左边的男人","半背对着、拿着牌的男人。"],["右边的男人","留胡子、拿着牌坐在桌边的男人。"],["瓶子","右边男人身旁的瓶子。"],["遮阳棚","从棚顶垂下的叶饰和遮阳棚。"]]},"chatur":{"title":"恰图兰卡对局","artist":"佚名","date":"1805—1815年","place":"印度","game":"恰图兰卡","medium":"水粉、金，毛笔","size":"16.2×9.8厘米（画面）","credit":"","p":["这是一幅印度细密画。据美术馆记录，两位女子在玩一种叫恰图兰卡的棋戏，侍女拿着拂尘。恰图兰卡是印度古老的棋戏，被视为国际象棋的祖先。","白色拱柱下的红毯上，穿深蓝衣和穿橙衣的女子隔着格子棋盘相对而坐。穿橙衣的女子伸出手，像是在说话。画面四周围着一圈用黑白线勾边的深红框。"],"spots":[["棋盘","红毯上的格子棋盘。"],["深蓝衣女子","戴着金饰、伸手向棋盘的女子。"],["橙衣女子","伸出手与她相对的女子。"],["侍女","站在后面的侍女。"],["拂尘","侍女举着的拂尘。"],["红框","黑白线勾边的深红框。"]]},"shabbarat":{"title":"女眷居所之夜","artist":"佚名","date":"1760—1770年","place":"印度","game":"乔帕尔（帕奇西）","medium":"水粉、金，毛笔","size":"34.3×25.6厘米","credit":"","p":["这是一幅印度细密画。据美术馆记录，四位女子在宫殿宽敞的庭院里玩棋戏，这种游戏叫乔帕尔或帕奇西。她们围坐在十字形的布棋盘旁。","前排右边的女子手持三根长条骰子，正要掷出。她旁边倚着靠枕的是地位最高的女子。虽是夜晚，露台上处处放着灯，远处城墙上也点着无数灯火。记录认为，这里可能在庆祝伊斯兰节日“拜拉特夜”。"],"spots":[["十字形棋盘","铺在地上的十字形棋盘。"],["拿骰子的女子","前排手持长条骰子的女子。"],["倚靠枕的女子","地位最高的女子。"],["侍女","端着托盘走来的女子。"],["灯","玻璃罩里燃着的蜡烛。"],["远处的亭子","有喷泉的庭园、亭子和城中灯火。"]]},"govase":{"title":"仕女弈棋图卵形瓶","artist":"佚名（“唐金堂”印）","date":"1724年","place":"中国（广东）","game":"围棋","medium":"瓷器，釉上彩（粉彩）、描金","size":"高15.3厘米","credit":"","p":["这是一只用极薄瓷胎、釉上彩绘制的中国花瓶。背面题有“博弈图，甲辰花朝写于岭南珠江精舍”，并有红印“唐金堂”。它是海牙收藏家罗耶尔瓷器收藏中的一件。","两位女子隔着桌上的棋盘对坐，左边的女子手持棋罐。右边有两位女子和两个孩子探身观看。后面的几案上陈设着插孔雀翎的花瓶、珊瑚等古玩。"],"spots":[["棋盘","桌上的棋盘和黑白棋子。"],["左边的棋手","拿着棋罐、伸指的女子。"],["右边的棋手","俯身向棋盘的女子。"],["观棋的女子们","从后面探看棋局的女子们。"],["孔雀翎与珊瑚","几案花瓶里的孔雀翎和珊瑚。"],["棋罐","左边女子手里的棋罐。"]]},"yokihi":{"title":"唐玄宗与杨贵妃双陆","artist":"佚名（摺物）","date":"1822年","place":"日本","game":"盘双六（双陆）","medium":"多色木版画，金属颜料","size":"21.6×19.1厘米","credit":"","p":["摺物是把画与狂歌等诗配在一起、用厚纸和金属粉奢华印制的版画，由诗人们订制，作为送给同好的礼物。这一张印着一首狂歌和诗人名“橘五园”。","据美术馆记录，画的是唐玄宗（685—762年）与宠妃杨贵妃（719—756年）玩双六，这种游戏与西洋双陆、特里克特拉克同类。红色小台上放着箱形棋盘，上面排着黑白棋子。"],"spots":[["棋盘","红台上的箱形双六盘和棋子。"],["杨贵妃","头戴花饰、手放在棋盘上的杨贵妃。"],["玄宗","手托下巴看棋盘的玄宗。"],["狂歌","左上的一首诗和诗人名。"],["屏风","后面画着山的屏风。"],["署名与印","右下的署名和朱印。"]]},"disderi":{"title":"穿水手服装打牌的男人们","artist":"迪斯德里公司","date":"1850—1890年","place":"法国（巴黎）","game":"纸牌","medium":"蛋白照片（名片照）","size":"8.6×5.3厘米","credit":"","p":["这张名片照贴在相册里，背面印着巴黎“迪斯德里公司（意大利人大道8号）”。迪斯德里就是推广了“名片照”——像名片一样一次印很多张的小照片——的摄影师。","戴三角帽、穿长外衣和白袜子的旧式打扮的男人们，围着有花纹的桌子打牌。美术馆记录说是“水手服装”，但应是演戏或化装用的服装。中间的男人站起来探看桌面。"],"spots":[["桌子","有花纹边饰的桌子，上面有牌和杯子。"],["站起来的男人","戴三角帽、探身看桌子的男人。"],["左边的男人","拿着牌坐着的男人。"],["右边的男人","戴三角帽、拿着牌的男人。"],["带扣的鞋","白袜和带扣的鞋。"],["金框","围着照片的衬板金框。"]]},"gans":{"title":"鹅棋（74格螺旋）","artist":"扬·奥尔特曼（父），据丹尼尔·威廉·斯托彭达尔设计","date":"1763—1823年","place":"荷兰","game":"鹅棋（掷骰赛跑游戏）","medium":"木刻（蓝、红、绿着色）","size":"40.8×46.8厘米","credit":"","p":["这是一张在荷兰印制的螺旋形赛跑棋盘。据美术馆说，格子从1排到74，有些格子里有图。刻版的是扬·奥尔特曼，设计者斯托彭达尔的名字带着“invenit（设计）”印在右下角。","终点74是中央夕阳下海边的神殿。格子里写着“LEER GELD（学费）”“DWAALWEG（歧路）”“DOMHEID / WYSHEID（愚蠢／智慧）”等词，还有拿大镰刀的骷髅“EINDE（终结）”，应是讲人生道路的教训游戏。"],"spots":[["74：神殿","终点神殿，立在夕阳下的海边。"],["1：起点","左下第一格。"],["学费","“LEER GELD”格，应是停在这里要付钱。"],["歧路","写着“DWAALWEG”的林间小路。"],["终结","拿大镰刀的骷髅“EINDE”。"],["骰子","画着两颗骰子的格子。"]]},"merelle":{"title":"梅雷尔棋与风筝","artist":"克洛迪娜·斯特拉（据雅克·斯特拉原画）","date":"1657年","place":"法国（巴黎）","game":"梅雷尔（九子棋）","medium":"雕版画","size":"11.7×14.1厘米","credit":"","p":["这是画家雅克·斯特拉设计、由他的侄女克洛迪娜刻成的儿童游戏系列的第17幅。据美术馆说，它出自一本装订了51幅版画的册子。玩耍的是胖嘟嘟的裸体小孩（普托）。","左前方，孩子们在石台上刻出的棋盘上下“梅雷尔”（九子棋）。右边地上画着方格和对角线，是往方格里扔硬币的“方格掷币”游戏，远处一个孩子拉着风筝奔跑。下面的诗说，每种游戏大家都玩得很用心。"],"spots":[["梅雷尔棋盘","刻在石台上的棋盘和棋子。"],["风筝","高高飞着的风筝。"],["放风筝的孩子","拉着线奔跑的孩子。"],["方格掷币","地上画的方格和对角线。"],["指着的孩子","手拿东西、指着地上线条的孩子。"],["标题","“LA MERELLE, & LE CERF VOLANT”字样。"]]},"feldcards":{"title":"在花园桌边打牌的人们（立体照片）","artist":"佚名","date":"1850—1880年","place":"不详（背面有格罗宁根店铺印章）","game":"纸牌","medium":"蛋白照片（立体照片）","size":"8.5×17.0厘米","credit":"","p":["这张立体照片拍的是在常春藤爬满格子篱的花园里，像是一家人或朋友们围桌打牌。背面盖着荷兰格罗宁根“费尔特布吕赫公司”的印章，应是出售它的店铺或出版商。","左边留胡子的男人高高举起一张牌，好像马上要拍到桌上。托着腮的男人、拿着牌的少年、白发老人和在后面看着的女子，一起留下了牌局的一瞬间。因为大家必须长时间不动，这应是摆好姿势的场面。"],"spots":[["举起的牌","留胡子的男人高举的一张牌。"],["桌上","已经出到桌上的牌。"],["少年的手牌","背对我们的少年拿着的牌。"],["白发老人","坐在右边的老人。"],["看着的女子","站在后面看牌局的女子。"],["刺绣椅子","前面蒙着花布的椅子。"]]},"tempel":{"title":"游戏盘《幸运神殿》","artist":"佚名","date":"1816年","place":"荷兰","game":"掷骰赛跑游戏","medium":"木刻，活字印刷文字","size":"43.0×48.5厘米","credit":"","p":["这是一张1到74格呈螺旋排列的游戏单页。中央画着海边的圆形神殿；同一收藏中保存的规则纸称它为“幸运神殿”，并说这是一种“投掷游戏”，也就是骰子游戏。","大多数格子是空白圆圈，但也有玫瑰、荆棘、骰子、铁门、渡船等图，以及“LEER GELD（学费）”“DOMHEID（愚蠢）”“WYSHEID（智慧）”等字。这应是一种劝善的赛跑游戏，经过善行与恶行，奔向神殿。"],"spots":[["幸运神殿","中央海边的神殿，是终点74号。"],["1号格","从左下开始的起点。"],["学费","写着“LEER GELD”的格子。"],["骰子","上排画的两枚骰子。"],["渡船","下排“OVER HAAL（摆渡）”的图。"],["愚蠢与智慧","右边的“DOMHEID”“WYSHEID”。"]]},"verkeer":{"title":"微型盘（费尔凯尔棋盘）","artist":"佚名","date":"1690—1710年","place":"荷兰（阿姆斯特丹）","game":"费尔凯尔（双陆的一种）、国际象棋、九子棋","medium":"胡桃木，镶橄榄木、乌木、黄杨木、骨，铜件","size":"合上5.8×5.8厘米（展开11.6厘米）","credit":"","p":["这是一件边长仅约六厘米、能像盒子一样打开的游戏盘。外面是国际象棋盘和九子棋盘，里面是费尔凯尔（荷兰的一种双陆）的棋盘，用铜合页和小钩扣上。","里面还留着一枚骰子、九枚骨棋子、四枚乌木棋子和三枚小硬币。从美术馆的编号看，它应是佩特罗内拉·奥尔特曼娃娃屋的陈设之一。虽然很小，木镶嵌却很精细，做法和真正的棋盘一样。"],"spots":[["骰子","米粒大小的骰子。"],["骨棋子","白色的圆形骨棋子。"],["乌木棋子","黑色的乌木棋子。"],["三角格","明暗木料交替镶嵌的三角。"],["合页","对折用的铜合页。"],["小钩","扣上用的小铜钩。"]]},"silverbd":{"title":"银质微型棋盘与棋子","artist":"弗雷德里克·范·斯特兰特二世","date":"1739年","place":"荷兰（阿姆斯特丹）","game":"国际跳棋、九子棋","medium":"银","size":"5.4×5.4厘米","credit":"","p":["这是一件仅5.4厘米见方的银棋盘：64格的盘面，边缘立起，并有挂环。深色格刻着细线，背面刻着九子棋的线。","上面打着阿姆斯特丹城徽、表示1739年的年代字母“E”，以及银匠弗雷德里克·范·斯特兰特二世的印记。随盘留存着15枚跳棋子，8枚有花纹，7枚有圆圈纹。应是放在娃娃屋或陈列柜里的银质微型器物。"],"spots":[["花纹棋子","压出花纹的棋子。"],["圆纹棋子","有圆圈纹的棋子。"],["挂环","棋盘角上的环。"],["刻纹格","刻着细线的深色格。"],["光面格","打磨光滑的浅色格。"],["边缘","棋盘四周立起的边。"]]},"schaak1550":{"title":"骑马棋子的国际象棋","artist":"佚名","date":"1550年","place":"德国","game":"国际象棋","medium":"黄杨木、针叶木","size":"最大棋子高10.5厘米","credit":"","p":["每枚棋子都立在旋制的底座上，四周围着花饰栏杆，上面雕着人物和马。国王和王后骑着马或骡，像是要去打猎。","据美术馆记录，黑方国王骑着一匹踏着龙、后腿直立的马，颈上挂着让人想起金羊毛骑士团的链子，或许表示他是查理五世。王后侧坐在骡上，手上停着鹰。最右边还有一枚滑稽的棋子：猴子骑在人背上。"],"spots":[["国王","戴冠、留须的骑马国王。"],["王后","侧坐骑骡、手托猎鹰的王后。"],["猴子棋子","骑在人背上的猴子。"],["滑稽的棋子","最左边一人骑在另一人背上。"],["脚下的生物","蹲在马蹄下的龙和兽。"],["底座","围着花饰栏杆的旋制底座。"]]},"kraaij":{"title":"在客厅玩棋的男女","artist":"佚名","date":"1900—1910年","place":"应为荷兰","game":"双陆（西洋双陆）","medium":"日光显影珂罗酊银盐照片","size":"8.0×11.1厘米","credit":"","p":["这是某个家庭相册中的一张，相册里还有葡萄酒商“克赖公司（波尔多—阿姆斯特丹）”的照片。在挂着吊灯的客厅里，像是家人或熟人的男女围坐在桌边。","桌上打开着折叠式的盒形棋盘，左右两位女子各拿着骰盅。美术馆记录写的是“棋戏”，但从盒形棋盘和骰盅看应是双陆。旁边有咖啡杯，后面有鸟笼，传达出家中夜晚的悠闲。"],"spots":[["盒形棋盘","打开的折叠盒子做成的棋盘。"],["左边的骰盅","戴眼镜的女子拿着的骰盅。"],["右边的骰盅","穿圆点衣服的女子正要摇的骰盅。"],["鸟笼","后面台子上的鸟笼。"],["吊灯","从天花板垂下的玻璃灯罩吊灯。"],["站着的男人","站在右边俯看牌局的男人。"]]},"braekel":{"title":"下跳棋的老夫妇","artist":"费迪南德·德·布雷克莱尔（父）","date":"1862年","place":"比利时（安特卫普）","game":"跳棋","medium":"蚀刻版画","size":"21.8×16.5厘米","credit":"","p":["这是安特卫普画家德·布雷克莱尔（1792—1883年）的蚀刻版画，左下签着“Ferdinand De Braekeleer Antwerpen 1862”。在有壁炉的旧厨房里，一位老翁和一位老妇隔着小桌对坐。","桌上棋盘排着圆棋子，老翁拈起一枚，老妇张开手像在回嘴。地上放着帽子，也掉了几枚棋子。架子上摆着盘子，窗外能看到房屋。"],"spots":[["棋盘与棋子","桌上的棋盘和圆棋子。"],["老翁","俯身拈起棋子的男人。"],["老妇","戴头巾、张手说话的女人。"],["地上的帽子","放在地上的老翁的帽子。"],["签名","“Ferdinand De Braekeleer Antwerpen 1862”。"],["架上的盘子","壁炉上方架子上的大盘子。"]]},"billiard":{"title":"台球","artist":"据H. W. 班伯里原画（刻者佚名）","date":"1780年","place":"英国（伦敦）","game":"台球","medium":"蚀刻与点刻","size":"30.0×39.1厘米","credit":"","p":["这是据英国漫画家亨利·威廉·班伯里原画制作的版画，1780年由伦敦的沃森与迪金森店出版。据美术馆说，是一套系列中的第4幅。","两个男人在打台球，周围的人屏息观看。一人探身在台上架起球杆，另一人把球杆扛在肩上。墙上有杆架和两个计分用的圆盘。美术馆说球台看起来像三角形。"],"spots":[["球台与球","铺着布的球台和上面的球。"],["瞄准的人","探身在台上出杆的男人。"],["扛杆的人","拿着长杆等候的男人。"],["计分盘","墙上两个圆盘，应是计分用具。"],["杆架","靠墙立着的一排球杆。"],["笑着的两人","右边凑在一起笑的观众。"]]},"baizi":{"title":"百子图（局部）","artist":"徐扬宏","date":"18世纪","place":"中国","game":"围棋","medium":"手卷，纸本水墨（淡设色）","size":"29.8×526厘米（全卷）","credit":"","p":["这是从中国职业画家徐扬宏所作、长五米多的手卷中截取的下棋场面。庭园里一百个孩子在游戏、奏乐、读书、写字。“百子”是亚洲艺术的重要题材，象征多子多福、家族兴旺。","这卷画也因日本的谷文晁后来临摹而闻名，摹本也藏于同一美术馆。芭蕉和太湖石旁，孩子们围着矮几上的棋盘，两人拿着棋罐对弈，其他孩子探头观看。"],"spots":[["棋盘","矮几上的棋盘和棋子。"],["落子的孩子","穿蓝衣、手伸进棋罐的孩子。"],["另一位棋手","俯身向棋盘的白衣孩子。"],["抱头的孩子","在后面抱着头看的孩子。"],["太湖石","满是孔洞的大奇石。"],["羽扇","左边拿羽扇的孩子。"]]},"schenkcards":{"title":"玩纸牌的两位中国女子","artist":"彼得·申克（子）","date":"1727—1775年","place":"荷兰（题材为中国）","game":"纸牌","medium":"蚀刻版画","size":"16.5×26.2厘米","credit":"","p":["这是阿姆斯特丹出版商兼版画家小彼得·申克出版的中国风人物与风景版画集《新创中国人》第一部中的一页。这是欧洲流行的“中国风”版画，画的是想象中的中国。","据美术馆记录，两位中国女子在庭园里玩纸牌，右边一位女子端着盛满食物的托盘走来。桌上的牌看起来像欧洲的扑克牌。左边台子上卧着一只兔子，河上漂着一艘帆船。"],"spots":[["桌上的牌","铺在桌上的纸牌，看来像欧洲的牌。"],["左边的女子","拿着牌看着对手的女子。"],["右边的女子","把牌放到桌上的女子。"],["端托盘的女子","端着盛满食物的托盘的女子。"],["兔子","卧在左边台子上的兔子。"],["帆船","河上的帆船。"]]},"gosaucer":{"title":"弈棋人物图盘","artist":"佚名","date":"1725—1735年","place":"中国","game":"围棋","medium":"瓷器，釉上彩（粉彩）、描金","size":"口径16.4厘米","credit":"","p":["这是一只用柔和的釉上彩“粉彩”绘制的中国盘子。底部画着用双圈围起的笔、如意和墨锭标记。美术馆的记录有的说是“一男一女下棋”，有的说是“三位女子中两人下棋”，对人物的看法不一。","屋内桌上放着棋盘，两人相对落子，另一人站在后面观看。桌上有黄色棋罐，后面是放花瓶的几架，右边画着一只大青罐。"],"spots":[["棋盘","桌上的棋盘和棋子。"],["左边的棋手","穿淡紫衣、倚着桌子的人。"],["右边的棋手","穿粉衣落子的人。"],["观棋的人","站在后面观看的人。"],["花瓶","几架上的插花瓶。"],["青罐","右边的大罐。"]]},"cheetham":{"title":"小小的纸牌聚会（在俄国）","artist":"佚名","date":"1903—1904年","place":"俄国","game":"纸牌","medium":"日光显影明胶银盐照片","size":"9.2×11.5厘米","credit":"","p":["这张照片来自住在俄国的英国奇瑟姆家族的相册，衬纸上用英语写着“a little card-party（小小的纸牌聚会）”。美术馆记录说，照片里的人大概是来拜访约瑟夫·奇瑟姆的英国朋友。","在贴着壁纸的房间里，三个人围着铺花纹桌布的桌子，展开手牌。桌上立着两座烛台，中间的女子把牌像扇子一样打开，笑着。这应是在遥远异乡与同乡朋友共度的轻松时光。"],"spots":[["左边男人的手牌","留胡子的男人展开的牌。"],["女子的手牌","中间的女子扇形展开的牌。"],["右边的男人","探身拿着牌的男人。"],["烛台","桌上的两座烛台。"],["桌布","有花和图案的大桌布。"],["题字","衬纸上的“a little card-party”。"]]},"problem":{"title":"难题（下国际象棋的男女·立体照片）","artist":"佚名","date":"1852—1863年","place":"不详","game":"国际象棋","medium":"立体照片（上色）","size":"8.4×17.4厘米","credit":"","p":["英文标题是“The Problem（难题）”。两位戴白色假发、穿18世纪风格服装的人在雕饰桌边下棋，被做成上了色的一对立体照片。背面手写着“Simons”。","年轻的一方双手捧着脸颊盯着棋盘，对面的年长男子则咧嘴笑着。这应是一眼就能看出谁遇到难题的、像戏剧一样的场面。脚边趴着一只狗。"],"spots":[["棋盘与棋子","雕饰桌上的棋盘和棋子。"],["苦思的人","双手捧着脸颊盯着棋盘的人。"],["笑着的男人","穿蓝色外衣、咧嘴笑的年长男子。"],["狗","趴在脚边的狗。"],["红色帷幕","背景中上了色的帷幕。"],["另一张","右边的照片，用立体镜看会有纵深。"]]},"tarocco":{"title":"塔罗牌中的十张","artist":"佚名（应据朱塞佩·玛丽亚·米泰利设计）","date":"1660—1718年","place":"意大利（博洛尼亚）","game":"塔罗基（塔罗牌游戏）","medium":"蚀刻与雕版，部分用浅褐色手工上色","size":"贴在衬纸上的十张","credit":"","p":["这是从博洛尼亚制作的一副塔罗牌中取出的十张牌，并排贴在衬纸上。塔罗牌起初不是用来占卜，而是用来玩有王牌的纸牌游戏。上排最左是标题牌，美术馆认为其中的肖像或许是画家米泰利。","上排是戴冠的人、骑马的人等四个人物，下排是“金币”花色的6到10，每张印着相应数量的金币。版画的线条上，部分涂了浅褐色。"],"spots":[["标题牌","左上，有肖像画框和题字的牌。"],["戴冠的男人","拿着权杖、戴冠的人物。"],["站着的女子","戴冠、手持杯子的女子。"],["骑马的人","骑在马上的人物牌。"],["金币10","下排左边，十枚金币。"],["金币6","下排右边，六枚金币。"]]},"kindtegel":{"title":"儿童游戏瓷砖","artist":"佚名","date":"1680—1730年","place":"荷兰","game":"儿童游戏（踩高跷、荡秋千等）","medium":"锡釉陶器（代尔夫特瓷砖），青色彩绘","size":"107×80厘米（48块）","credit":"","p":["这是由竖8块、横6块、共48块瓷砖拼成的一整面。每块砖上用蓝色小小地画着两个玩耍的孩子，四角各有一个叫作“蜘蛛”的小装饰。","有踩高跷的，有被人推着荡秋千的，有蹲在地上玩东西的，每块砖画的游戏都不一样。这类“儿童游戏”瓷砖在荷兰很受欢迎，应是贴在厨房或壁炉周围的墙上。"],"spots":[["高跷","踩着高跷的孩子。"],["秋千","被推着荡秋千的孩子。"],["地上的游戏","蹲在地上摆弄东西的孩子。"],["蜘蛛纹","瓷砖四角的小装饰。"],["48块的排列","竖8块、横6块的瓷砖。"],["右下角的一块","右下角的瓷砖。"]]},"dammolen":{"title":"跳棋与九子棋两用的微型棋盘","artist":"佚名","date":"1740—1760年","place":"荷兰（阿姆斯特丹）","game":"国际跳棋、九子棋","medium":"胡桃木，浅色填料","size":"4.2×4.0×1.5厘米","credit":"","p":["这是一块宽约四厘米的胡桃木小棋盘，近似正方形，边缘立起。一面可作跳棋盘，另一面可作九子棋盘。","跳棋那面把格子刻出来再填入浅色填料，和木头本色组成格纹；九子棋那面刻出的线也用同样的填料填平。这么小，应是为娃娃屋做的。"],"spots":[["填料格","刻出后填入浅色填料的格子。"],["木色格","保留胡桃木本色的格子。"],["边缘","四周立起的边。"],["近角","离我们最近的角。"],["厚度","高1.5厘米的侧面。"],["最里一排","最里面一排格子。"]]},"karelpiece":{"title":"刻有查理大帝像的跳棋子（半面）","artist":"佚名","date":"1525—1575年","place":"德国（纽伦堡）","game":"跳棋或双陆","medium":"黄杨木","size":"直径5.3厘米","credit":"","p":["这是一枚黄杨木雕的跳棋子的一面。中央是月桂冠环绕的侧面像，四周刻着“CAROLVS. MAGNVS. IMPER. AVGVST.（查理大帝，皇帝）”。","美术馆藏有十几枚同样做法的棋子，分别刻着提比略、阿格里皮娜、虔诚者路易、奥托大帝等从古罗马到中世纪的皇帝和皇后。应是把历代君主做成一套棋子的奢华游戏用具。"],"spots":[["侧面像","月桂冠环绕的查理大帝侧面像。"],["月桂冠","围着肖像的月桂环。"],["CAROLVS","上方的“CAROLVS. MAGNVS”字样。"],["AVGVST","左边的“IMPER. AVGVST”字样。"],["星","铭文间隔用的小星。"],["边缘","棋子边上的台阶。"]]},"vdberge":{"title":"荷兰的游戏，美好生活！（打牌）","artist":"彼得·范登贝赫（设计并出版）","date":"1694—1737年","place":"荷兰（阿姆斯特丹）","game":"纸牌","medium":"蚀刻（红、蓝、绿套色）","size":"27.3×17.0厘米","credit":"","p":["这是阿姆斯特丹版画家兼出版商范登贝赫的讽刺画，题为“LE JEU HOLLANDOIS. LA BELLE VIE!”。据美术馆说，酒馆里男人们在打牌，一个举杯叹气的男人身边和桌下，魔鬼们正赢走他的钱。","下方荷兰语诗中，这个无忧无虑的浪荡子哀叹斗狗、斗鸡、纸牌和骰子把他的钱花光了。两侧两个魔鬼用德语引诱他：在骰子和纸牌上快活吧。后墙的画上也画着斗狗和斗鸡。"],"spots":[["举杯的男人","戴大假发举着酒杯的浪荡子。"],["手牌","男人手里展开的纸牌。"],["左边的魔鬼","在他身后咧嘴笑的魔鬼。"],["桌下的魔鬼","搂走撒在地上的钱币的魔鬼。"],["斗狗斗鸡图","墙上画着斗狗和斗鸡。"],["标题与诗","“LE JEU HOLLANDOIS”和浪荡子的哀叹诗。"]]},"crespi":{"title":"掷骰子的孩子们","artist":"朱塞佩·玛丽亚·克雷斯皮","date":"1675—1747年","place":"意大利","game":"骰子","medium":"蚀刻版画","size":"22.5×15.1厘米","credit":"","p":["这是博洛尼亚画家克雷斯皮亲手刻制的蚀刻版画。据美术馆说，四个孩子在街边玩骰子，下面附有三行意大利语诗。","蹲着的孩子刚把骰子掷在地上，另外三人在旁观看。诗里说到骨头（骰子）和数字、短暂的游戏、钱越来越少，应是在孩子的游戏里也寄寓了对赌博的告诫。"],"spots":[["骰子","滚在地上的小骰子。"],["蹲着的孩子","刚掷出骰子的孩子。"],["站着的孩子","俯身探看的孩子。"],["右边的孩子","坐在地上看着的孩子。"],["后面的孩子","从别人身后探出头的孩子。"],["诗","三行意大利语诗。"]]},"epinal":{"title":"大鹅棋（埃皮纳尔版）","artist":"佩尔兰公司（埃皮纳尔）","date":"1791—1900年","place":"法国（埃皮纳尔）","game":"鹅棋（掷骰赛跑游戏）","medium":"木刻（黄、红、绿、蓝着色），活字印刷文字","size":"39.8×59.0厘米","credit":"","p":["这是法国东部埃皮纳尔的佩尔兰版画工坊印制的彩色单页，上方用法语写着“GRAND JEU DE L’OIE”。据美术馆说，63格螺旋里画着鹅、其他动物和人物，中央印着荷兰语标题“GANZENBORD!”和玩法。","据玩法，掷两枚骰子，停在鹅的格子可以再前进同样的步数。6号桥去12，19号客栈停两轮，31号井要等到别人来，42号迷宫退回30，58号死亡回到起点。必须正好到达63才算赢。左右两边排着可剪下用的筹码。"],"spots":[["63：鹅","终点63，池上的鹅。"],["玩法","中央印的荷兰语规则。"],["剪下的筹码","两侧带数字的圆形筹码。"],["标题","上方的“GRAND JEU DE L’OIE”。"],["玩耍的孩子","左下角玩耍的孩子们。"],["工坊名","左上的“PELLERIN & Cie”。"]]},"matham":{"title":"玩特里克特拉克的男女","artist":"雅各布·马塔姆（出版），西蒙·索维乌斯作诗","date":"1621年","place":"荷兰（哈勒姆）","game":"特里克特拉克（双陆的一种）","medium":"雕版画","size":"17.9×20.0厘米","credit":"","p":["这是哈勒姆版画家兼出版商马塔姆出版的四幅一套系列中的第3幅。据美术馆说，衣着华丽的男女在房间的小桌上玩特里克特拉克并下注；桌上放着钱袋，女子手里拿着骰子。","棋盘上细长的三角格和黑白棋子刻得清清楚楚。下面有拉丁语和荷兰语诗，荷兰语诗告诫说：不只是饮酒过度会扰乱心神，游戏和赌博也有违一切利益。后面一个少年举着葡萄酒杯。"],"spots":[["棋盘","排着三角格和棋子的特里克特拉克棋盘。"],["走棋的男人","戴帽子、伸手到棋盘上的男人。"],["拿骰子的女子","大领子的女子，手拿骰子。"],["举杯的少年","后面举着葡萄酒杯的少年。"],["钱袋","桌上装赌注的钱袋。"],["诗","拉丁语和荷兰语的告诫诗。"]]},"jardin":{"title":"在花园桌边打牌的三个男人和旁观者（法国）","artist":"佚名（法国业余摄影师）","date":"1900—1910年","place":"法国","game":"纸牌","medium":"蛋白照片","size":"11.8×17.2厘米","credit":"","p":["这张照片来自一位法国业余摄影师的相册，相册里还有家人、蒸馏酒公司“德利齐与杜瓦斯托”、军队和法国各地名胜的照片。","在铺着砾石的花园树荫下，三个男人围着小桌打牌，一位白胡子的年长男子站在后面观看。桌上放着牌，戴硬草帽的男人盯着手牌。这应是家人或朋友间轻松的一幕。"],"spots":[["桌上的牌","已经出到桌上的牌。"],["旁观者","白胡子的年长男子，从后面看牌局。"],["戴草帽的男人","中间盯着手牌的男人。"],["右边的男人","穿深色外衣、拿着牌的男人。"],["左边的男人","穿浅色上衣的男人。"],["花园","铺砾石的花园和树丛。"]]},"lamplight":{"title":"打牌的人们（灯下）","artist":"佚名","date":"1900—1910年","place":"不详","game":"纸牌","medium":"显影明胶银盐照片","size":"7.5×10.0厘米","credit":"","p":["这是贴在某本相册里的小照片，美术馆的标题是“打牌的人们”。拍摄者和地点都不清楚。","在天花板垂下的油灯光下，穿条纹衣服的女子、女孩和男孩们围着铺流苏桌布的桌子，把手牌像扇子一样展开。在暗室里拍照应该很难，这应是想留下家人夜晚团聚的一张照片。"],"spots":[["流苏桌布","有花纹和流苏的桌布。"],["油灯","从天花板垂下的油灯。"],["条纹衣服的女子","穿白条纹衣服坐着的女子。"],["女子的手牌","女子像扇子一样拿着的牌。"],["女孩的手牌","中间的女孩展开的牌。"],["右边的男孩","探身拿着牌的男孩。"]]},"borduur":{"title":"刺绣牌局的牌桌桌面","artist":"佚名","date":"1700—1725年","place":"不详","game":"纸牌","medium":"彩色毛线和丝线的粗针绣与细针绣","size":"100×185厘米","credit":"","p":["这是一张折叠式牌桌桌面上的刺绣，用多色毛线和丝线，分用粗针的大十字绣和细针的小十字绣。在切去四角的形状里，围着一圈涡卷和花朵的饰框。","中央的风景里，两位夫人和一位绅士围着桌子打牌。据美术馆记录，桌上放着钱袋、纸牌和其他游戏用具。在打牌用的桌子上绣上打牌的场面，十分别致。"],"spots":[["桌面","放着钱袋和纸牌的绿色桌子。"],["绅士","坐在左边戴帽子的男子。"],["中间的夫人","坐在桌子后面的夫人。"],["右边的夫人","穿蓝衣坐着的夫人。"],["树木","人物身后茂密的树。"],["饰框","涡卷和花朵的边框。"]]},"piquet":{"title":"印有皮克牌的布","artist":"佚名","date":"1725—1750年","place":"不详","game":"皮克牌（纸牌游戏）","medium":"亚麻布，红紫两色印花","size":"73.0×82.5厘米","credit":"","p":["这是一块铺在牌桌上的亚麻布，满满印着红紫两色的纸牌游戏用具。美术馆记录也把它称作手帕。","边框和中央散布着皮克牌（用7到A共32张牌玩的游戏）的牌，中间画着钱袋，四周是筹码。国王、王后、杰克的人头牌是带有凯撒、阿尔金、奥吉耶等名字的“巴黎式”。"],"spots":[["钱袋","中央画的赌注钱袋。"],["人头牌","巴黎式的国王和王后牌。"],["筹码","圆形筹码。"],["纸牌边框","布四周排满纸牌的边。"],["背面朝上的牌叠","露出背面花纹的牌叠。"],["封好的牌包","右下封好的牌包。"]]},"schaakglas":{"title":"刻有两人下国际象棋的高脚杯","artist":"佚名","date":"1815—1830年","place":"不详","game":"国际象棋","medium":"无色透明玻璃，轮刻","size":"高13.7厘米","credit":"","p":["这是一只带脚的透明玻璃杯，用旋转的小砂轮刻出图画和文字。在立着两支蜡烛的小桌旁，两个男人隔着棋盘相对。","左边的人戴眼镜、叼着烟斗，右边的人俯身看棋盘，桌上还放着酒杯。四周刻着法语：“懂走法很简单，懂棋局是天赋的果实。”"],"spots":[["棋盘","摆着棋子的棋盘。"],["叼烟斗的人","左边戴眼镜、叼烟斗的人。"],["俯身的人","右边凑近看棋的人。"],["蜡烛","棋盘那边的两支蜡烛。"],["酒杯","桌上的杯子。"],["铭文","用法语刻的文字。"]]},"arlequin":{"title":"阿勒坎的乐透游戏","artist":"佚名（明德曼公司出版）","date":"1818—1845年","place":"荷兰（阿姆斯特丹）","game":"乐透/赛跑游戏","medium":"雕版，手工上色，裱于厚纸板","size":"不详","credit":"","p":["这是一张把叉腿站立的阿勒坎（丑角）本身做成棋盘的游戏版画。绿衣的身体和两腿之间，排着1到32号的方格。下方有“Arlequin’s Lotto-Spel”的标题和阿姆斯特丹明德曼公司的名字。","他脸上戴着网面罩，手里拿着帽子和像木剑的东西。有些格子标着“HW”或“P”。这张手工上色的版画裱在厚纸板上，应是当作棋盘用的。"],"spots":[["网面罩","遮住脸的网罩。"],["1号格","左腿下的起点格。"],["HW格","标着“HW”的格子。"],["P32","标着“P”的32号格。"],["标题","下方的“Arlequin’s Lotto-Spel”。"],["帽子","右手拿的帽子。"]]},"vicaire":{"title":"副本堂神父的一局牌","artist":"勒内·加扬（据图版标注）","date":"1888—1893年","place":"法国","game":"纸牌","medium":"珂罗版（据美术馆记录）","size":"10.4×15.6厘米","credit":"","p":["这是刊登在《巴黎摄影俱乐部会刊》上的图版，题为“La partie du Vicaire（副本堂神父的一局牌）”。下方边上印着“Phototype René Gayant”“Héliogravure Lemercier”，应是加扬拍摄、勒梅西耶公司印制。书中是横着装订的。","挂着锅和平底锅的厨房里，穿黑色神父袍的神父坐在桌边盯着牌，对面的男人也拿着牌。戴帽子的男人托着腮，年轻人用手贴着耳朵看牌局。像绘画一样的光线和构图，很符合追求艺术摄影的摄影俱乐部。"],"spots":[["神父的手牌","神父在手边盯着的牌。"],["神父","穿黑袍、戴白领的神父。"],["拿牌的男人","卷发男人，低头看牌。"],["看牌的年轻人","手贴着脸颊看牌局的年轻人。"],["戴帽子的男人","托着腮的戴帽男人。"],["厨房墙","挂着锅和勺子的墙。"]]},"israels":{"title":"下国际象棋的人们","artist":"伊萨克·伊斯拉埃尔斯","date":"1875—1922年","place":"荷兰","game":"国际象棋","medium":"色粉画","size":"40.0×57.5厘米","credit":"","p":["这是以快速生动的笔触描绘阿姆斯特丹城市生活的荷兰画家伊萨克·伊斯拉埃尔斯（1865—1934年）的色粉画。窗户明亮的房间里，男人们围着棋盘。","前面两人一个手托脸颊、一个手托下巴，紧盯棋盘；后面一个戴帽子的男人探身来看。棋子没有细画，只用色点表示，仿佛长长的思考时间正在流逝。"],"spots":[["棋盘与棋子","桌上的棋盘，棋子用色点画成。"],["左边的棋手","手托脸颊看棋的人。"],["右边的棋手","手托下巴思考的人。"],["戴帽子的人","从后面探身来看的人。"],["窗户","左边明亮的窗户。"],["椅子","右前方的椅子。"]]},"louisxi":{"title":"路易十一与女儿安娜·德·博热","artist":"阿德里安·约瑟夫·费尔霍芬-巴尔","date":"1866年","place":"比利时（安特卫普）","game":"国际象棋","medium":"版画（应为蚀刻）","size":"26.4×31.3厘米","credit":"","p":["这是安特卫普画家费尔霍芬-巴尔自己画、自己刻的版画（下方有“pinx et sculp（绘并刻）”）。美术馆的标题是“路易十一与女儿安娜·德·博热下国际象棋”。下方还写着“安特卫普艺术家协会第二届展览”。","15世纪的法国国王路易十一穿着毛皮长袍坐在桌前，女儿安娜手托下巴看着棋盘。桌上有棋子和果盘，地上卧着一只狗，后面还站着手持兵器的卫兵。这应是想象中的历史父女场面。"],"spots":[["棋盘与棋子","桌上的棋盘和棋子。"],["路易十一","戴帽子、穿毛皮长袍的国王。"],["安娜","手托下巴看棋的女儿。"],["卧着的狗","卧在地上的细长的狗。"],["后面的卫兵","暗处持兵器的卫兵。"],["标题","“LOUIS XI ET SA FILLE ANNE DE BEAU-JEU”。"]]},"bruining":{"title":"下跳棋的修士们","artist":"蒂勒曼·卡托·布赖宁","date":"1750—1850年","place":"荷兰","game":"跳棋","medium":"蚀刻版画","size":"20.6×16.8厘米","credit":"","p":["这是荷兰版画家布赖宁的蚀刻版画，左下写着“T. Bruining inv. et fecit aqua fort（设计并蚀刻）”。据美术馆说，两位修士坐在桌旁下跳棋。","他们身后站着第三位修士和一个穿修士袍的魔鬼。桌边还站着同样扮成修士的“死神”，把大镰刀藏在背后。修士们沉迷于棋局，没有察觉悄悄进来的不速之客。"],"spots":[["跳棋棋盘","桌上的棋盘和棋子。"],["死神","穿修士袍、把大镰刀藏在背后的死神。"],["后面的两个","第三位修士和穿修士袍的魔鬼。"],["左边的棋手","俯身在棋盘上的修士。"],["右边的棋手","手臂搭在桌上思考的修士。"],["签名","“T. Bruining inv. et fecit aqua fort”。"]]},"vanvliet":{"title":"烛光下的特里克特拉克","artist":"扬·希利斯·范弗利特","date":"1631—1634年","place":"荷兰（莱顿）","game":"特里克特拉克（双陆的一种）","medium":"蚀刻与雕版","size":"15.2×13.4厘米","credit":"","p":["这是与伦勃朗同在莱顿工作的版画家范弗利特的作品。据美术馆说，在左边有华盖床的昏暗房间里，两人在玩特里克特拉克，右边有一男一女。","穿黑衣的男人背对我们深深俯身看棋盘，对面的人笑着把手搭在棋盘边上。棋盘上的三角格和棋子清晰可见。看不到光源，只有棋盘和人脸被照亮，应是夜里的一局。"],"spots":[["棋盘","能看到三角格和棋子的特里克特拉克棋盘。"],["笑着的棋手","手搭棋盘边、笑着的人。"],["俯身的人","背对我们、俯身看棋的黑衣男人。"],["戴帽子的人","站在后面、戴宽檐帽的男人。"],["戴褶领的人","右边举手的戴褶领的人。"],["床帐","左边华盖床的帘子。"]]},"hermans":{"title":"围着棋盘的两位女子和小女孩","artist":"弗朗索瓦·赫尔曼斯（照相馆）","date":"1857—1895年","place":"荷兰（鹿特丹）","game":"国际象棋","medium":"蛋白照片（名片照）","size":"10.1×6.2厘米","credit":"","p":["这张名片照贴在家庭相册里，背面印着照相馆名“François Hermans / Hang 421 / Rotterdam”。应是在照相馆拍的家庭纪念照。","小圆桌上放着国际象棋盘，左边的女子手搭在棋子上，右边的女子托腮思考。两人之间站着的小女孩正直直地看着我们。在长时间曝光中，三人大概都一动不动。"],"spots":[["棋盘","圆桌上的棋盘和棋子。"],["移动棋子的手","左边女子把手搭在棋子上。"],["小女孩","站在棋盘后面看着我们的小女孩。"],["思考的女子","托腮的右边女子。"],["脚凳","地上的圆脚凳。"],["窗户","右后方的格子窗。"]]},"norimberg":{"title":"刻有纽伦堡城景的跳棋子","artist":"佚名","date":"1690年","place":"德国（纽伦堡）","game":"跳棋或双陆","medium":"黄杨木","size":"直径5.4厘米，厚1.5厘米","credit":"","p":["这是一枚黄杨木跳棋子，浮雕着塔楼和城堡林立的纽伦堡城景。上方刻着“SVB AQVILAE ROMANAE ALIS QVIESCO（我栖息于罗马之鹰的翼下）”，下方刻着“NORIBERGA VRBIVM REGINA（城市之后纽伦堡）”。","据美术馆记录，另一面刻有皇帝约瑟夫一世和七位选帝侯的肖像。应是把神圣罗马帝国的帝国城市纽伦堡的自豪刻进了游戏用具。"],"spots":[["城景","教堂尖塔和城墙林立的纽伦堡。"],["上方铭文","“SVB AQVILAE ROMANAE…”字样。"],["下方铭文","“NORIBERGA VRBIVM REGINA”字样。"],["纹饰","最上方的小纹饰。"],["城堡","右边高处的城堡。"],["边缘","棋子边上的台阶。"]]},"toovenaar":{"title":"赛跑游戏《魔法师》","artist":"佚名","date":"1856年","place":"荷兰（阿姆斯特丹）","game":"赛跑游戏（鹅棋的一种）","medium":"石版画，活字印刷文字，手工上色","size":"44.5×53.5厘米","credit":"","p":["这是一张题为“DE TOOVENAAR（魔法师）／新颖有趣的儿童游戏”、1到63格螺旋排列的赛跑游戏。中央画着站在摆有骷髅、圣杯、月亮和星星的桌前的魔法师，身后有恶魔般的生物；四角也有兽头恶魔。","印在中央的规则和鹅棋差不多：掷两枚骰子，第一次掷出6和3就到26，5和4就到53。落到魔法师格要像鹅格那样再走一次；过桥付一，进酒馆付二并停一回，到42号迷宫退三格，碰到死神要付钱并从头开始。"],"spots":[["魔法师","中央桌前的魔法师。"],["标题与规则","“DE TOOVENAAR”的标题和玩法。"],["终点63","螺旋最后一格。"],["角上的恶魔","四角的兽头恶魔。"],["外圈的格子","带图的格子沿外圈排列。"],["桌上的器物","摆着骷髅和圣杯的桌子。"]]},"fichesdoos":{"title":"象牙筹码盒","artist":"小马里亚瓦尔","date":"1725年","place":"法国（巴黎）","game":"纸牌游戏的筹码","medium":"象牙","size":"2×8×6厘米","credit":"","p":["这是一个巴掌大的象牙盒，装着纸牌游戏中代替钱的筹码。盒盖上画着坐在云上、戴冠持杖的女子和孔雀，以及两枚纹章。带着孔雀的女子应是女神朱诺。","据美术馆记录，盖上写着“Mariaval le Jeune a Rouen fecit（鲁昂的小马里亚瓦尔制）”，底面画着鹰和群鸟，其中一只吊在绞架上。盒里还留着画有昆虫和花的大筹码19枚、小筹码6枚。"],"spots":[["戴冠的女子","坐在云上戴冠的女子。"],["孔雀","女子脚边的孔雀。"],["纹章","右上并排的两枚纹章。"],["小鸟","女子身旁栖木上的鸟。"],["云","托着女子的云。"],["盖缘","盒盖的边缘和扣件。"]]},"vuilmere":{"title":"下跳棋的画家母亲","artist":"爱德华·维亚尔","date":"约1890—91年","place":"法国","game":"跳棋（国际跳棋）","medium":"粉彩、铅笔，擦笔与擦拭·象牙色纸","size":"37.5×30.5厘米","credit":"","p":["这是法国画家维亚尔画母亲的粉彩画。维亚尔和母亲同住，一次又一次地画当裁缝的母亲家中的场景。右下角有“E Vuillard”的签名。","两位穿黑衣的人隔着鲜艳的橙色桌子坐着，前面的人手里拿着跳棋盘。据美术馆的标题，画中是画家的母亲。在椭圆形的黑线里，人和家具融成一块块色彩与形状。"],"spots":[["棋盘","黑白相间的棋盘。"],["后面的人","坐在桌子那边的黑衣人。"],["前面的人","拿着棋盘的人。"],["橙色桌子","铺满画面的鲜艳颜色。"],["花纹墙","用卷曲线条画的墙面花纹。"],["签名","右下的“E Vuillard”。"]]},"dewitte":{"title":"下国际象棋的两个男人","artist":"阿德里安·德维特","date":"1877年","place":"比利时","game":"国际象棋","medium":"应为蚀刻","size":"13.2×12.5厘米","credit":"","p":["这是比利时列日的画家、版画家德维特（1850—1935年）的一幅小版画。据美术馆说，研究文献（克莱克斯，1981年）认为下棋的两人是特尔姆和泽延。","铺着桌布的桌旁，年轻人抱着胳膊俯视棋盘，对面年长的人手扶着头沉思。棋盘后面还能看到像是棋子盒的东西。细线层层叠加的昏暗房间里，一局棋静静进行。"],"spots":[["棋盘与棋子","桌上的棋盘和棋子。"],["棋子盒","棋盘后面像是盒子的东西。"],["年轻人","抱着胳膊俯视棋盘的人。"],["年长的人","手扶着头思考的人。"],["桌布","铺在桌上的布。"],["椅子","左边曲木椅的椅背。"]]},"orphans":{"title":"孤儿们（下跳棋的孩子）","artist":"查尔斯·罗尔斯（据W. 吉尔原画）","date":"1810—1834年","place":"英国","game":"跳棋","medium":"版画（雕版）","size":"22.6×13.9厘米","credit":"","p":["这是一幅下方题为“THE ORPHANS（孤儿们）”的版画，写着“W. 吉尔画，C. 罗尔斯刻”。据美术馆说，它可能用于伦敦出版的年刊礼品书《纪念册》（The Keepsake）。","厨房里，一个女孩和一个男孩把棋盘放在木桶上下跳棋。后面一位妇女在刺绣，里面还有美术馆称为织布机的器具。从标题看，两个孩子应是被这位妇女收养的孤儿。"],"spots":[["跳棋棋盘","放在木桶上的棋盘和棋子。"],["女孩","探身看棋盘的女孩。"],["男孩","移动棋子的男孩。"],["刺绣的妇女","后面做针线的妇女。"],["水罐","放在地上的水罐。"],["标题","下方的“THE ORPHANS”。"]]},"richelieu":{"title":"路易十三与黎塞留","artist":"扬·弗雷德里克·克里斯蒂安·雷克勒本","date":"1850年","place":"荷兰（阿姆斯特丹）","game":"国际象棋","medium":"钢版画","size":"24.2×29.6厘米","credit":"","p":["这是阿姆斯特丹版画家雷克勒本的钢版画，上方写着“1850. NEDERLANDSCH MUSEUM. Pl. II.”。据美术馆说，它可能是杂志《荷兰博物馆》一篇文章的插图。","在大壁炉前，法国国王路易十三和宰相黎塞留枢机主教在下国际象棋，周围聚着一群男人。坐在左边的枢机主教伸手拿棋子，戴羽毛帽的国王从容地坐着。最左边站着一位抱臂的修士。"],"spots":[["棋盘","铺布的桌上的棋盘和棋子。"],["黎塞留","伸手拿棋子的枢机主教。"],["路易十三","戴羽毛帽的国王。"],["修士","在最左边抱臂观看的修士。"],["围观的廷臣","聚在右边的男人们。"],["标题","下方的“LODEWIJK DE XIII EN RICHELIEU”。"]]},"coster":{"title":"烛光下玩特里克特拉克的人们（据德科斯特）","artist":"据亚当·德科斯特油画（福斯特曼刻）","date":"1619—1628年","place":"佛兰德","game":"特里克特拉克（双陆的一种）","medium":"雕版画","size":"37.1×35.1厘米","credit":"","p":["这是据以烛光画著称的佛兰德画家亚当·德科斯特的油画制作的版画，下方有“A. De Coster pi.”和“Vorsterman”字样。据美术馆说，两个男人站在桌前借着烛光玩特里克特拉克。","左边一个叼烟斗的男人在旁观看，右边一个少女弹着鲁特琴，一个戴帽子的男人指着蜡烛。前面的人背对我们俯身在桌上，对面的人把手悬在棋盘上方。只有一支蜡烛照亮场面，只映出脸和手。"],"spots":[["棋盘","桌上半隐在暗处的棋盘。"],["蜡烛","照亮全场的一支蜡烛。"],["背对的棋手","俯身在桌上的棋手。"],["对面的棋手","把手悬在棋盘上方的人。"],["抽烟斗的人","在左边抽着烟斗观看的人。"],["弹鲁特琴的少女","右边弹鲁特琴的少女。"]]},"kiebitz":{"title":"旁观者（看牌的人）","artist":"汉斯·瓦采克","date":"1894年","place":"应为奥地利","game":"纸牌","medium":"网版印刷（书中插图）","size":"10.0×12.1厘米","credit":"","p":["这是维也纳艺术摄影家汉斯·瓦采克的照片，右上角签有“HANS WATZEK 94”。它以网版印在一本页眉写着“摄影是艺术吗？”的书里。","德语标题“Kiebitz”原指凤头麦鸡，也是俗语，指在牌局旁插嘴的看客。戴帽子的男人盯着手牌，前面叼长烟斗的男人从旁边探看。粗粒的、像绘画一样的调子，是当时追求接近绘画的艺术摄影的特色。"],"spots":[["手牌","右边男人盯着的牌。"],["拿牌的男人","戴圆顶礼帽、叼着烟斗的男人。"],["看客","叼长烟斗的男人，应是标题里的“Kiebitz”。"],["啤酒杯","桌上的玻璃啤酒杯。"],["签名","右上的“HANS WATZEK 94”。"],["标题","下方的“HANS WATZEK. — KIEBITZ.”。"]]},"evdvelde":{"title":"城堡花园里玩特里克特拉克的人们","artist":"埃萨亚斯·范德费尔德","date":"1630年","place":"荷兰","game":"特里克特拉克（双陆的一种）","medium":"黑粉笔、灰色淡彩","size":"18.5×30.1厘米","credit":"","p":["这是荷兰风俗画和风景画的先驱之一埃萨亚斯·范德费尔德（1587—1630年）的素描，右下签着“E.V.VELDE”。据美术馆说，衣着华丽的人们在城堡花园里围着桌子玩特里克特拉克。","一个站着俯身的男人和一个坐着的男人隔着棋盘，后面有女士们观看。左前方是冰酒器和两只酒壶，再往里是喷泉边的少年和孔雀。这是在户外游戏的优雅午后。"],"spots":[["棋盘","桌上的特里克特拉克棋盘。"],["俯身的男人","戴帽子、俯身向棋盘的男人。"],["坐着的男人","翘着腿对着棋盘的男人。"],["观看的女士","站在后面看棋的女士。"],["孔雀与少年","喷泉边的孔雀和少年。"],["冰酒器","左前方的器皿和两只酒壶。"]]},"cooghen":{"title":"玩特里克特拉克的两个男人","artist":"莱恩德特·范德库亨","date":"1666年","place":"荷兰（哈勒姆）","game":"特里克特拉克（双陆的一种）","medium":"蚀刻版画","size":"9.3×15.6厘米","credit":"","p":["这是哈勒姆画家范德库亨的蚀刻版画，棋盘上方的墙上刻着“1666”年份。据美术馆说，酒馆里两个男人在桌边玩特里克特拉克，一位女子从左边男人的肩后探看。","左边年长的男人穿毛皮镶边外衣，手拿高脚杯；右边年轻男人戴着显眼的羽饰帽子。窗边坐着一只小猴子。棋盘的边框和三角格刻得很清楚。"],"spots":[["棋盘","桌上的特里克特拉克棋盘。"],["年长的男人","穿毛皮镶边外衣的男人。"],["酒杯","年长男人手里的高脚杯。"],["探看的女子","从左边男人肩后探看的女子。"],["窗边的猴子","坐在窗边的小猴子。"],["羽饰帽的人","戴羽饰帽子的年轻人。"]]},"roybet":{"title":"下棋的人","artist":"费迪南·鲁瓦贝","date":"1875年","place":"法国（巴黎）","game":"国际象棋","medium":"应为蚀刻","size":"26.1×19.6厘米","credit":"","p":["这是喜欢画17世纪骑士的法国画家鲁瓦贝自己画、自己刻的版画（左下有“F. Roybet del. et sc.”）。下方写着“LE JOUEUR D’ÉCHECS（下棋的人）”，右下有出版商卡达尔的名字。","戴羽毛帽、佩着剑的男人侧身坐在长凳上，伸手去拿棋子。看不到对手，他似乎在独自思考棋局。后面的架子上摆着啤酒杯、水壶和玻璃杯。"],"spots":[["棋盘与棋子","长凳上的棋盘和棋子。"],["骑士","戴羽毛帽的男人。"],["伸向棋子的手","伸手拿棋子的男人。"],["剑","腰间的长剑。"],["架上的器皿","啤酒杯、水壶和玻璃杯。"],["标题","“LE JOUEUR D’ÉCHECS”字样。"]]},"capot":{"title":"“圣彼得，朋友，你被‘卡波’了！”（画家与模特打牌）","artist":"佚名（奥贝尔公司出版）","date":"1838年","place":"法国（巴黎）","game":"纸牌（应为皮克牌）","medium":"石版画","size":"30.5×22.2厘米","credit":"","p":["这是刊登在巴黎讽刺报《喧闹报》1838年9月9日号上的石版画，上方标着“Les Artistes（艺术家们）”第13号。下方的台词是“圣彼得，朋友，你被‘卡波’了！”","据美术馆说，画家把牌友叫作“圣彼得”，因为这个人正是身后画中圣人的模特。“卡波”指在皮克牌中一墩也没拿到而大败，所以他们玩的应是皮克牌。"],"spots":[["桌上的牌","小桌上打出的牌。"],["模特","背对我们的长发男人，头发和胡子与画中圣人相同，应是模特。"],["画家","右边拿着手牌的男人，应是画家。"],["圣人画","画架上画了一半的圣人。"],["凳子","模特坐的木凳。"],["台词","“St. Pierre, mon ami, vous êtes capot!”。"]]},"ziacard":{"title":"梅花K（齐亚普韦布洛总督安东尼奥·萨尔瓦）","artist":"亚当·克拉克·弗罗曼（摄影）、拉扎勒斯与梅尔策（出版）","date":"1900年","place":"美国（洛杉矶）","game":"扑克牌","medium":"网目版照相印刷","size":"8.8×6.3厘米","credit":"","p":["据美术馆记录，这是一盒53张（含王牌）扑克牌中的一张，牌面用网目版印着美洲原住民的照片。照片由亚当·克拉克·弗罗曼拍摄，洛杉矶的拉扎勒斯与梅尔策出版。","梅花K上没有画国王，而是新墨西哥州齐亚普韦布洛总督安东尼奥·萨尔瓦的肖像。下方印着他的名字和头衔，角上有K和梅花标记。这副牌可能是为前往美国西部的游客制作的纪念品。"],"spots":[["角标","左上角的K和梅花，与普通扑克相同。"],["总督的脸","侧脸望向一旁的安东尼奥·萨尔瓦。"],["长发","齐肩的长发和剪齐的刘海。"],["领口的布","白衬衫领口系着的布巾。"],["名字和头衔","印着“安东尼奥·萨尔瓦，齐亚普韦布洛总督”。"],["倒置的角标","右下角倒着的K和梅花。"]]},"gothink":{"title":"下围棋的两位女子和一位男子","artist":"日本摄影师（佚名）","date":"1887—1897年","place":"日本","game":"围棋","medium":"手工上色照片（书中插图）","size":"8.8×13厘米","credit":"","p":["这张照片由一位佚名的日本摄影师拍摄，并在日本手工上色，贴在一本介绍日本的英文书第65页作插图。下方印的英文说明：“围棋是比国际象棋更难的游戏，8世纪从中国传入日本。”","榻榻米上隔着有脚的棋盘，左边的女子落子，白胡子老人手按头部陷入沉思。中间的女子注视棋盘，前面摆着点心盘和茶碗。这可能是为外国游客在照相馆里摆拍的。"],"spots":[["棋盘","有脚的棋盘上摆着棋子。"],["落子的手","左边女子把手伸向棋盘。"],["沉思的老人","白胡子老人手按着头。"],["观棋的女子","中间穿条纹和服、注视棋盘的女子。"],["点心盘","前面盘子里的点心。"],["棋罐","棋盘旁带盖的棋子罐。"]]},"craps":{"title":"少年赌徒","artist":"弗朗西斯·A·普莱斯","date":"1888—1893年","place":"可能是美国","game":"骰子","medium":"照片（书中插图）","size":"14×9.9厘米","credit":"","p":["据美术馆记录，照片拍的是四个身份不明的男孩玩骰子，衬纸上印着摄影师弗朗西斯·A·普莱斯的名字。它贴在一本书第142页之前两页，印有“印在美国‘Aristo’相纸上”“用威廉斯闪光灯装置拍摄”。它可能兼作相纸和闪光灯的样张。","铺着稻草的墙边，男孩们围着一只木箱。箱上有一个铁皮碟和两颗骰子。右边的男孩打着响指，坐在地上的男孩手托下巴盯着看。下方地面刻着“COME SEV”，可能是美国骰子赌博“克拉普斯”里喊“来个七！”的口号。"],"spots":[["两颗骰子","木箱上的两颗骰子。"],["铁皮碟","箱上的碟子，可能用来放赌注。"],["打响指的男孩","右边男孩对着骰子打响指。"],["坐着的男孩","坐在地上、手托下巴的男孩。"],["“COME SEV”","下方刻的字，可能是“来个七！”。"],["木箱上的字","箱侧印着的字母。"]]},"bikkel":{"title":"玩抓羊拐的男子习作","artist":"扬·巴普蒂斯特·韦尼克斯（推测）","date":"1642—1647年","place":"意大利（罗马）","game":"抓羊拐（掷骨游戏）","medium":"黑白粉笔，蓝纸","size":"26.7×18.0厘米","credit":"","p":["这是在蓝纸上用黑白粉笔画的素描。据美术馆说，可能是荷兰画家韦尼克斯在罗马时期所作；以前曾作为帕拉梅德斯的作品出售。","戴帽子的男人深深弯下腰，盯着手里；脚边地上散着几块小骨头。抛接羊等动物的踝骨是一种古老的游戏，常被说成是骰子的祖先。"],"spots":[["脸","从帽檐下看着手里。"],["手","应是正要抛骨头的手。"],["地上的骨头","地上散落的小骨头。"],["鞋","用力踩地的脚。"],["白粉笔","表现光线的白色粉笔。"],["斗篷","背上展开的斗篷。"]]},"stukken":{"title":"国际象棋棋子设计图","artist":"佚名（法国）","date":"1850—1875年","place":"法国","game":"国际象棋","medium":"钢笔黑墨水，白色与朱红不透明颜料，黑粉笔底稿，蓝纸","size":"26.5×20.0厘米","credit":"","p":["这是一套国际象棋棋子的设计图，作者不详，画于法国。上下两排各有王、后、车、人物棋子和马五种。","上排是戴冠的王和王后、跪着持枪的士兵；下排是缠头巾的王、戴面纱的王后和跪着拉弓的士兵，两方应是被设计成西方和东方的军队。白色和朱红颜料表现了雕刻与光泽。"],"spots":[["王（上）","戴冠、持权杖的王。"],["后（上）","戴冠的王后。"],["塔","作为车的塔。"],["持枪士兵","跪着持枪的棋子。"],["头巾王","下排的王。"],["弓箭手","下排拉弓的棋子。"]]},"rozetempel":{"title":"花园，或欢乐的玫瑰神殿（骰子游戏盘）","artist":"佚名（亨德里克·莫勒奈泽尔出版）","date":"1792—1847年","place":"荷兰（阿姆斯特丹）","game":"骰子游戏盘","medium":"版画","size":"46.1×39.6厘米","credit":"","p":["这是阿姆斯特丹出版商莫勒奈泽尔发行的单张游戏盘，上方标题是“BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL（花园，或欢乐的玫瑰神殿）”。","中央的“ROZE TEMPEL”里有一瓶玫瑰，周围一圈排着两颗骰子的点数组合和花。玩法应是掷两颗骰子，在对应的花那里付出或收取赌注。"],"spots":[["标题","“BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL”。"],["玫瑰神殿","中央的“ROZE TEMPEL”。"],["骰子点数","两颗骰子的点数组合。"],["玫瑰花瓶","神殿里的一瓶玫瑰。"],["郁金香","周围的花之一。"],["出版商","“Te AMSTERDAM bij H. Moolenyzer”。"]]},"brelan":{"title":"布雷朗（选自《童戏》）","artist":"克洛迪娜·斯特拉（据雅克·斯特拉原画）","date":"1657年","place":"法国（巴黎）","game":"布雷朗（三张牌的纸牌游戏）","medium":"雕版画","size":"12.0×14.2厘米","credit":"","p":["这是收录51个儿童游戏场面的画册《童年的游戏与乐趣》中的一页。诗句上方写着“LE BRELAN”，胖乎乎的孩子们坐在地上打牌。","诗里说：一个孩子滚着铁环，其他孩子挤在一起用纸牌碰运气，以为稳赢的那个反倒输了钱。布雷朗常被说成是扑克的远祖之一。"],"spots":[["手牌","展开手牌看的孩子。"],["地上的牌","地上一张标着“A”的牌。"],["偷看的孩子","从后面偷看手牌的孩子。"],["滚铁环","用棍子滚铁环的孩子。"],["塔","背景中的圆塔。"],["标题","“LE BRELAN”和诗句。"]]},"pwkarte":{"title":"六只鹦鹉的圆形纸牌","artist":"科隆的PW大师","date":"1470—1500年","place":"德国（科隆）","game":"纸牌（圆形牌）","medium":"雕版画","size":"直径7.0厘米","credit":"","p":["这是五百多年前用雕版印出的一张圆形纸牌。据美术馆说，它属于一副70张的圆牌，分为玫瑰、耧斗菜、康乃馨、鹦鹉和野兔五种花色。","每种花色有标1到10的数字牌10张，还有画人物的人头牌4张。这张是“鹦鹉6”，上方是阿拉伯数字“6”，下方是罗马数字“VI”，六只鹦鹉围着中央的装饰。"],"spots":[["“6”","上方的阿拉伯数字。"],["“VI”","下方的罗马数字。"],["上面的鹦鹉","像是停在枝上的鹦鹉。"],["展翅的鹦鹉","张开翅膀的鹦鹉。"],["倒挂的鹦鹉","头朝下的鹦鹉。"],["中央的装饰","放出光芒的中央装饰。"]]},"nilson":{"title":"棋盘游戏（跳棋与托卡迪耶）","artist":"约翰·埃萨亚斯·尼尔松","date":"1731—1788年","place":"德国（奥格斯堡）","game":"跳棋（国际跳棋）与托卡迪耶","medium":"蚀刻与雕版","size":"18.9×28.8厘米","credit":"","p":["这是奥格斯堡版画家尼尔松设计并出版的洛可可饰框版画，上方写着“Das Bretspiel（棋盘游戏）”，是四张一组中的第三张。","据美术馆说，左边桌上一男一女在下跳棋，右边桌上两个男人在玩托卡迪耶——一种双陆类游戏。下方德文诗句的意思是：玩托卡迪耶的人一心想赢，下跳棋的人要用尽全部心思。"],"spots":[["跳棋盘","左边桌上的跳棋盘。"],["托卡迪耶盘","右边小桌上的棋盘。"],["读信的男人","叼着烟斗读信的男人。"],["端器皿的女子","右边端着餐具的女子。"],["园景","饰框后面的公园。"],["诗句","“Wer Tocadille spielt…”。"]]},"chateau":{"title":"纸牌城堡","artist":"弗朗索瓦·茹兰（据夏尔-安托万·夸佩尔原画）","date":"1725年","place":"法国（巴黎）","game":"纸牌（搭纸牌屋）","medium":"雕版画","size":"23.2×15.8厘米","credit":"","p":["这是茹兰根据画家夸佩尔的原画刻制、由巴黎的迪尚日出版的版画。地上的一张纸上写着“CH. COYPEL”。","打扮华丽的孩子在桌上用纸牌搭城堡，后面的少年把手指放在嘴边看着。下方诗句嘲讽赌牌：笑这些孩子搭起一吹就倒的城堡的人，若从没把纸牌用在别处，倒也算个聪明人。"],"spots":[["纸牌城堡","桌上搭起的纸牌。"],["手中的牌","孩子手里拿的牌。"],["搭城堡的孩子","戴羽饰帽的孩子。"],["观看的少年","把手指放在嘴边的少年。"],["地上的纸","写着“CH. COYPEL”的纸。"],["诗句","“Tel qui rit, voyant ces Enfans…”。"]]},"pugillus":{"title":"输光骰子的青年与盛装女子","artist":"雅各布·范德海登（推测）","date":"1608—1618年","place":"法国（斯特拉斯堡）","game":"骰子","medium":"雕版画","size":"9.0×13.2厘米","credit":"","p":["这是面向学生的漫画版画集《Pugillus facetiarum iconographicarum》（一把图画笑话）中的一张，据美术馆说原本大概有36张以上。","左边是拿着扇子的盛装女子，右边是衣衫破烂的青年举起帽子，看着地上的两颗骰子和空钱袋。下方的话大意是“眼睛的天堂、心灵的地狱、钱袋的炼狱”和“从来没有现钱，裤子总是破的”，嘲笑沉迷女色和赌博。"],"spots":[["盛装女子","戴皮帽、穿长袍。"],["扇子","女子手里的羽毛扇。"],["举帽的青年","像打招呼一样举起帽子。"],["破衣服","破烂的上衣和裤子。"],["骰子与钱袋","地上的两颗骰子和空钱袋。"],["题词","“Nunquam bar gelt, semper zerrissen hosen”。"]]},"grootebroek":{"title":"赫罗特布鲁克的彩票","artist":"科内利斯·迪萨特","date":"1694—1695年","place":"荷兰（哈勒姆／阿姆斯特丹）","game":"彩票","medium":"美柔汀与雕版","size":"25.1×19.5厘米","credit":"","p":["1694年8月20日，恩克赫伊森附近的赫罗特布鲁克村发生大火，人们为受灾者举办了彩票。这是迪萨特的版画，由阿姆斯特丹的霍勒出版。","据美术馆说，一个男人把水壶和封好的信送到中奖者家。下方标题的意思是“看那丰厚奖品被欢天喜地地送回家”。吹号的男人、举起水壶的男人和在窗口举起双手的女人，传达了中奖的热闹。"],"spots":[["封好的信","送给中奖者的信。"],["水壶","举起奖品水壶的男人。"],["号角","吹号报喜的男人。"],["窗口的女人","惊喜地举起双手。"],["狂欢的人们","右边喝酒庆祝的人。"],["标题","“Lottery van Groottenbroek”。"]]},"narren":{"title":"掷骰子的两个弄臣（伊拉斯谟《愚人颂》插图）","artist":"卡斯帕·梅里安（据汉斯·霍尔拜因与安布罗修斯·霍尔拜因素描）","date":"1516年（素描）","place":"瑞士（巴塞尔）","game":"骰子","medium":"蚀刻版画","size":"5.5×6.0厘米","credit":"","p":["这是伊拉斯谟《愚人颂》书中的一幅小插图。最初是霍尔拜因兄弟1516年在学者米科尼乌斯所藏书的页边画的素描，梅里安把它刻成版画，用于1676年在巴塞尔出版的版本。","戴着带铃铛小丑帽的男人和戴兜帽的男人隔着圆桌掷骰子，桌上有三颗骰子。光着的脚让人想起沉迷赌博的愚人。"],"spots":[["骰子","桌上的三颗骰子。"],["戴小丑帽的人","左边探身的弄臣。"],["铃铛","小丑帽尖上的铃铛。"],["戴兜帽的人","右边看着对手的人。"],["兜帽的铃铛","兜帽垂尾上的铃铛。"],["光脚","桌下光着的脚。"]]},"historiespel":{"title":"祖国历史游戏棋","artist":"约翰内斯·克里斯蒂安·本多普","date":"1816年","place":"荷兰（阿姆斯特丹）","game":"掷骰竞走棋（鹅棋型）","medium":"蚀刻与雕版","size":"50.3×61.0厘米","credit":"","p":["这是一张走过荷兰历史的棋盘，由阿姆斯特丹的哈特曼出版。据美术馆说，它和鹅棋一样排着1到80的格子，1是“巴达维人起义”，80是“阿姆斯特丹航海学校”。","它改编自1787年的版本，第70到79格的事件被换掉，画中最新的事件是1816年的。另有一张说明玩法的纸。格子里排满战斗场面和英雄肖像，应是边玩边学历史的棋盘。"],"spots":[["起点1","左下的第1格。"],["终点80","中央的航海学校。"],["标题","“VADERLANDSCH HISTORIESPEL”。"],["肖像格","画着人物肖像的格子。"],["70多号格","内圈的70多号格。"],["出版商","“HENDRIK GARTMAN”的名字。"]]},"daumier":{"title":"永远不会被警察监视的巴黎人","artist":"奥诺雷·杜米埃","date":"1847年","place":"法国（巴黎）","game":"跳棋（国际跳棋）","medium":"石版画","size":"29.7×22.6厘米","credit":"","p":["这是讽刺画家杜米埃的石版画，刊登在巴黎《喧闹报》1847年8月25日号上。上方有组画标题“TOUT CE QU’ON VOUDRA（随你所欲）”和第12号。","房间里的小桌边，两位老人在下跳棋，中间的人托着腮看棋盘。下方的话是“永远不会被高等警察监视的巴黎人”，应是在调侃这些安分下棋的老人。"],"spots":[["棋盘","桌上的跳棋盘。"],["走棋的人","左边伸手拿棋子的人。"],["看棋的人","中间托腮的人。"],["右边的人","盯着棋盘的人。"],["墙上的画","后墙上的画框。"],["题词","“Parisiens qui ne seront jamais placés…”。"]]},"arnauts":{"title":"下跳棋的阿尔瑙特人","artist":"亨利·奥古斯丁·瓦朗坦（据让-莱昂·热罗姆原画）","date":"1856—1886年","place":"法国（巴黎）","game":"跳棋（国际跳棋）","medium":"版画（应为蚀刻）","size":"21.7×27.0厘米","credit":"","p":["这是瓦朗坦根据法国画家热罗姆的画刻制、由巴黎古皮尔公司出版的版画，下方写着“ARNAUTES JOUANT AUX DAMES（下跳棋的阿尔瑙特人）”。阿尔瑙特人是为奥斯曼帝国效力的阿尔巴尼亚士兵。","据美术馆说，两个阿尔瑙特人在长凳上面对面下跳棋。左边的人穿着多褶裙般的服装，手里摆弄着什么；右边的人叼着长烟管俯看棋盘。左边墙上能看到热罗姆的签名。"],"spots":[["棋盘","两人之间的跳棋盘。"],["左边的人","穿多褶服装坐着的人。"],["手","摆弄东西的手。"],["右边的人","俯看棋盘的人。"],["烟管","右边的人叼着的长烟管。"],["签名","左墙上热罗姆的签名。"]]},"luyken":{"title":"抽烟下棋的土耳其人","artist":"扬·勒伊肯","date":"1698年","place":"荷兰（阿姆斯特丹／代尔夫特出版）","game":"国际象棋","medium":"蚀刻与雕版","size":"30.5×19.1厘米","credit":"","p":["这是勒伊肯为旅行家科内利斯·德布勒因的《小亚细亚游记》（代尔夫特，1698年）第136页刻的插图。一块版上有上下两个场面，上为A，下为B。","上面的场面里，六个戴头巾的男人用长烟管抽烟，其中两人在地毯上下国际象棋；下面是四个喝咖啡的女人和一个侍女。台座前沿整齐地摆着脱下的鞋。"],"spots":[["棋盘","地毯上的棋盘。"],["下棋的人","伸手拿棋子的人。"],["俯身的人","俯看棋盘的人。"],["烟管","用长烟管抽烟的人们。"],["脱下的鞋","前面摆成一排的鞋。"],["窗外的树","窗外的树木。"]]}};
